@charset "UTF-8";
/* chat-v1.3 (mode sombre + bascule) (base : widget v6 du 2026-09-30) — copie de travail chat-version */
/* Widget custom Appsmith — Portail SMS / Appels manqués (onglet CSS) */
:root {
  --primary: var(--appsmith-theme-primaryColor, #166ee1);
  --sidebar-bg: #d3e5fb;
  --sidebar-hover: #c4dbf8;
  --sidebar-active: #b8d3f6;
  --sidebar-active-line: #8eb5ea;
  --text: #1d1f25;
  --muted: #616670;
  --faint: #9aa0a8;
  --line: #eceef1;
  --line-strong: #dfe2e6;
  --hover: #f6f7f9;
  --green-bg: #d1f7c4;
  --green-tx: #0e5b12;
  --green-bar: #9fe29a;
  --red-bg: #e3002b;
  --red-tx: #ffffff;
  --red-bar: #f8b7ad;
  --blue-bg: #d4e8ff;
  --blue-tx: #0b4a8b;
  --blue-bar: #9cc6f4;
  --gray-bg: #eef0f3;
  --gray-tx: #3b3f46;
  --tag-bg: #e9eef6;
  --row-h: 39px;
  /* mode sombre (chat-v1.3) : valeurs claires = couleurs d'origine, aucun changement visuel en mode clair */
  --surface: #fff;
  --surface-raised: #fff;
  --field-bg: #fff;
  --field-muted: #f7f8fa;
  --on-text: #fff;
  --primary-ink: var(--primary);
  --danger: #c2261b;
  --danger-solid: #c2261b;
  --danger-bg: #fff1f0;
  --danger-ink: #9b1c12;
  --danger-line: #d6453d;
  --danger-border: #f3b6b0;
  --note-bg: #fff8e1;
  --note-tx: #8a5a00;
  --nav-active-fly: #e3e6ea;
  --brand-ico-bg: rgba(255,255,255,.35);
  --toast-bg: #1d1f25;
  --toast-tx: #fff;
  --shadow-pop: rgba(15, 20, 30, .12);
  --shadow-drawer: rgba(15, 20, 30, .10);
  --shadow-fly: rgba(15, 20, 30, .16);
  --shadow-side: rgba(0,0,0,.12);
  --bubble-in: #fff;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 13px;
  color: var(--text);
  background: var(--surface);
  overflow: hidden;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}

svg {
  display: block;
}

[hidden] {
  display: none !important;
} /* sinon .tool { display:flex } écrase l'attribut hidden */
.app {
  display: flex;
  height: 100vh;
  width: 100vw;
  position: relative;
  overflow: hidden;
}

.app.compact {
  --row-h: 31px;
}

/* ---------- Barre latérale ---------- */
.app {
  --side-w: var(--side-w-user, 236px);
  --rail-w: 52px;
}

.sidebar {
  width: var(--side-w);
  flex: 0 0 var(--side-w);
  background: var(--sidebar-bg);
  display: flex;
  flex-direction: column;
  position: relative;
}

.app:not(.resizing) .sidebar {
  transition: width 0.16s ease, flex-basis 0.16s ease;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 18px 14px 14px 16px;
}

#brandLogo {
  width: 30px;
  height: 30px;
  object-fit: contain;
  flex: none;
}

.brand-ico {
  width: 30px;
  height: 30px;
  flex: none;
}

.brand-name {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.01em;
}

.brand-name .chev {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-left: 6px;
  vertical-align: 1px;
  color: var(--muted);
}

.nav {
  flex: 1;
  overflow-y: auto;
  padding: 6px 8px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  padding: 7px 10px;
  border-radius: 6px;
  color: var(--text);
  line-height: 1.2;
}

.nav-item:hover {
  background: var(--sidebar-hover);
}

.nav-item svg {
  width: 16px;
  height: 16px;
  flex: none;
  color: var(--text);
}

.nav-item.scope-active {
  font-weight: 600;
}

.nav-sub {
  margin: 2px 0 8px 17px;
  padding-left: 7px;
  border-left: 2px solid var(--sidebar-active-line);
}

.nav-sub .nav-item {
  padding: 7px 10px;
  color: var(--muted);
}

.nav-sub .nav-item.active {
  background: var(--sidebar-active);
  color: var(--text);
  font-weight: 600;
  box-shadow: inset 0 0 0 1px var(--sidebar-active-line);
}

.nav-gap {
  height: 14px;
}

.side-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
}

.side-foot .push-right {
  margin-left: auto;
}

.avatar-btn {
  cursor: pointer;
  border: 0;
}

.avatar-btn:hover {
  filter: brightness(0.94);
}

.bell {
  position: relative;
}

.bell .badge {
  position: absolute;
  top: -3px;
  right: -4px;
  min-width: 14px;
  height: 14px;
  padding: 0 3px;
  border-radius: 7px;
  background: var(--text);
  color: var(--on-text);
  font-size: 9px;
  line-height: 14px;
  text-align: center;
}

/* ---------- Zone principale ---------- */
.main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 52px;
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 16px 0 24px;
  border-bottom: 1px solid var(--line);
}

.icon-btn.show-nav {
  display: none;
} /* visible seulement sur petit écran (voir @media) */
.crumbs {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  white-space: nowrap;
  overflow: hidden;
}

.crumbs .sep {
  width: 12px;
  height: 12px;
  color: var(--faint);
}

.crumbs .cur {
  font-weight: 600;
}

.crumbs button {
  padding: 2px 4px;
  border-radius: 4px;
}

.crumbs button:hover {
  background: var(--hover);
}

.tools {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}

.tool {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 6px;
  white-space: nowrap;
}

.tool:hover, .icon-btn:hover {
  background: var(--hover);
}

.tool.danger {
  color: var(--danger);
}

.tool.danger:hover {
  background: var(--danger-bg);
}

.tool.danger .count:not(:empty) {
  background: var(--danger-solid);
  color: #fff;
}

.icon-btn.danger {
  color: var(--danger);
}

.icon-btn.danger:hover {
  background: var(--danger-bg);
}

.tool .ico {
  width: 16px;
  height: 16px;
}

.tool .chev {
  width: 12px;
  height: 12px;
  color: var(--muted);
}

.count:not(:empty) {
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--text);
  color: var(--on-text);
  font-size: 11px;
  line-height: 18px;
  text-align: center;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 6px;
}

.icon-btn svg {
  width: 18px;
  height: 18px;
}

.search {
  width: 0;
  overflow: hidden;
  transition: width 0.18s ease;
}

.search.open {
  width: 220px;
}

.search input {
  width: 100%;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  font: inherit;
  outline: none;
}

.search input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 18%, transparent);
}

.menu-wrap {
  position: relative;
}

.popover {
  display: none;
  position: absolute;
  top: 36px;
  left: 0;
  z-index: 20;
  min-width: 200px;
  padding: 6px;
  background: var(--surface-raised);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: 0 8px 24px var(--shadow-pop);
}

.popover.right {
  left: auto;
  right: 0;
}

.popover.open {
  display: block;
}

.popover button, .popover label {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 8px;
  border-radius: 6px;
  text-align: left;
  cursor: pointer;
}

.popover button:hover, .popover label:hover {
  background: var(--hover);
}

.popover .pop-title {
  padding: 6px 8px 4px;
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.popover .pop-reset {
  color: var(--primary);
}

.page-desc {
  flex: none;
  padding: 0 24px 16px;
  margin-top: -8px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
}

.main.has-desc .topbar {
  border-bottom: 0;
}

/* ---------- Table ---------- */
.grid-wrap {
  flex: 1;
  overflow: auto;
  padding: 0 24px 0 56px;
  position: relative;
}

.grid {
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  width: max-content;
  min-width: 100%;
}

.grid thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--surface);
  height: 42px;
  padding: 0 8px;
  font-size: 11px;
  font-weight: 400;
  color: var(--muted);
  text-align: left;
  white-space: nowrap;
  border-bottom: 1px solid var(--line);
  user-select: none;
}

.grid thead th.sortable {
  cursor: pointer;
}

.grid thead th.sortable:hover {
  color: var(--text);
}

.th-in {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
}

.th-in .lbl {
  overflow: hidden;
  text-overflow: ellipsis;
}

.th-in .arrow {
  width: 12px;
  height: 12px;
  margin-left: auto;
  color: var(--muted);
}

.resizer {
  position: absolute;
  top: 8px;
  right: 0;
  width: 7px;
  height: 26px;
  cursor: col-resize;
}

.resizer::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 0;
  width: 1px;
  height: 100%;
  background: transparent;
}

th:hover .resizer::after {
  background: var(--line-strong);
}

.resizer.dragging::after {
  background: var(--primary);
}

.grid th.gutter, .grid td.gutter {
  width: 40px;
  padding: 0;
}

.grid tbody tr {
  cursor: pointer;
}

.grid tbody td {
  height: var(--row-h);
  padding: 0 8px;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: middle;
}

.grid tbody tr:hover td, .grid tbody tr.selected td {
  background: var(--hover);
}

.grid td.first {
  position: relative;
  padding-left: 12px;
}

.grid td.first::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  border-radius: 2px;
  background: var(--bar, var(--line-strong));
}

td.gutter .chk {
  opacity: 0;
  width: 15px;
  height: 15px;
  margin: 0 0 0 12px;
  cursor: pointer;
  accent-color: var(--primary);
}

tr:hover td.gutter .chk, td.gutter .chk:checked {
  opacity: 1;
}

.muted-cell {
  color: var(--faint);
  font-style: italic;
}

.grid td.wrap {
  white-space: normal;
  line-height: 1.55;
}

.grid td.wrap .clamp {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.grid tr.tall td {
  height: 86px;
  vertical-align: top;
  padding-top: 14px;
  padding-bottom: 12px;
}

.grid tr.tall td.gutter .chk {
  margin-top: 2px;
}

.grid tr.add-row {
  cursor: default;
}

.grid tr.add-row td {
  height: 40px;
  border-bottom: 0;
  background: transparent !important;
}

.add-btn {
  color: var(--muted);
  padding: 4px 6px;
  border-radius: 6px;
}

.add-btn:hover {
  background: var(--hover);
  color: var(--text);
}

/* Pastilles */
.tag, .pill, .chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: middle;
}

.tag {
  padding: 3px 7px;
  border-radius: 4px;
  background: var(--tag-bg);
}

.pill {
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--gray-bg);
  color: var(--gray-tx);
}

.pill.green {
  background: var(--green-bg);
  color: var(--green-tx);
}

.pill.red {
  background: var(--red-bg);
  color: var(--red-tx);
}

.pill.blue {
  background: var(--blue-bg);
  color: var(--blue-tx);
}

.chip {
  padding: 2px 8px 2px 3px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--surface);
}

.avatar {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 700;
  flex: none;
}

.avatar.lg {
  width: 26px;
  height: 26px;
  font-size: 12px;
}

.dt-time {
  color: var(--text);
  margin-left: 16px;
}

.empty {
  padding: 40px 0;
  text-align: center;
  color: var(--muted);
}

.foot {
  flex: none;
  height: 26px;
  padding: 4px 10px;
  font-size: 11px;
  color: var(--muted);
}

/* ---------- Panneau de détails ---------- */
.drawer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 380px;
  max-width: 92vw;
  z-index: 30;
  background: var(--surface-raised);
  border-left: 1px solid var(--line-strong);
  box-shadow: -12px 0 32px var(--shadow-drawer);
  display: flex;
  flex-direction: column;
  transform: translateX(105%);
  transition: transform 0.2s ease;
}

.drawer.open {
  transform: translateX(0);
}

.drawer-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}

.drawer-title {
  font-size: 16px;
  font-weight: 700;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 8px 16px;
}

.field {
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}

.field .k {
  font-size: 11px;
  color: var(--muted);
  margin-bottom: 5px;
}

.field .v {
  min-height: 20px;
}

.field .v.msg-preview {
  white-space: pre-wrap;
  line-height: 1.55;
  background: var(--field-muted);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
}

.drawer-foot {
  padding: 12px 16px;
  border-top: 1px solid var(--line);
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.btn {
  padding: 8px 14px;
  border-radius: 6px;
  border: 1px solid var(--line-strong);
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  font-weight: 600;
}

.btn.primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.warn {
  margin: 12px 0 4px;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--danger-bg);
  color: var(--danger-ink);
  font-size: 12px;
}

@media (max-width: 760px) {
  .sidebar {
    position: absolute;
    z-index: 40;
    height: 100%;
    box-shadow: 8px 0 24px var(--shadow-side);
  }
  .grid-wrap {
    padding: 0 12px;
  }
  .search.open {
    width: 140px;
  }
}
/* ---------- Mode modification ---------- */
.btn-edit {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--line-strong);
  font-weight: 500;
  white-space: nowrap;
}

.btn-edit:hover {
  background: var(--hover);
}

.btn-edit[hidden] {
  display: none;
}

.btn-edit.btn-edit-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn-edit.btn-edit-primary:hover {
  background: var(--primary);
  opacity: 0.9;
}

.edit-form {
  padding: 6px 0;
}

.edit-field {
  display: block;
  padding: 8px 0;
}

.edit-field .k {
  display: block;
  font-size: 11px;
  color: var(--muted);
  margin-bottom: 6px;
}

.edit-field .req {
  color: var(--danger);
}

.edit-field input, .edit-field select, .edit-field textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  font: inherit;
  color: var(--text);
  background: var(--field-bg);
  outline: none;
}

.edit-field textarea {
  resize: vertical;
  line-height: 1.5;
}

.edit-field input:focus, .edit-field select:focus, .edit-field textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 18%, transparent);
}

.edit-field.has-error input, .edit-field.has-error select, .edit-field.has-error textarea {
  border-color: var(--danger-line);
}

.edit-field .err {
  display: block;
  margin-top: 5px;
  font-size: 12px;
  color: var(--danger);
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 24px;
  z-index: 50;
  transform: translate(-50%, 16px);
  opacity: 0;
  padding: 10px 16px;
  border-radius: 8px;
  background: var(--toast-bg);
  color: var(--toast-tx);
  font-weight: 500;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Pied de barre : menu du compte + notifications ---------- */
.popover.up {
  top: auto;
  bottom: 40px;
  left: 0;
  z-index: 60;
}

.user-menu {
  min-width: 240px;
}

.um-head {
  padding: 8px 10px 6px;
}

.um-name {
  font-weight: 600;
}

.um-mail {
  margin-top: 2px;
  font-size: 12px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
}

.um-sep {
  height: 1px;
  margin: 6px 0;
  background: var(--line);
}

.notif-panel {
  width: 340px;
  max-width: 86vw;
  padding: 12px;
  left: -60px;
}

.notif-panel .np-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.notif-panel .np-title {
  font-weight: 600;
}

.notif-panel .np-tabs {
  display: flex;
  gap: 2px;
  padding: 2px;
  border-radius: 8px;
  background: var(--hover);
}

.notif-panel .np-tabs button {
  width: auto;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 12px;
  color: var(--muted);
}

.notif-panel .np-tabs button.on {
  background: var(--surface-raised);
  color: var(--text);
  font-weight: 600;
  box-shadow: 0 1px 2px var(--shadow-pop);
}

.notif-panel .np-search {
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  font: inherit;
  outline: none;
}

.notif-panel .np-search:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 18%, transparent);
}

.np-list {
  max-height: 300px;
  min-height: 120px;
  overflow-y: auto;
  margin-top: 8px;
}

.np-empty {
  padding: 44px 8px;
  text-align: center;
  color: var(--faint);
}

.notif-panel .np-item {
  align-items: flex-start;
  padding: 8px;
  gap: 10px;
}

.np-dot {
  flex: none;
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--blue-bar);
}

.np-dot.red {
  background: #e3002b;
}

.np-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.np-txt small {
  color: var(--muted);
  font-size: 12px;
  white-space: normal;
}

.notif-panel .np-markall {
  justify-content: center;
  margin-top: 8px;
