}

/* ---------- Barre latérale : redimensionnement ---------- */
.sidebar-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(100% - 3px);
  width: 6px;
  cursor: col-resize;
  z-index: 35;
}

.sidebar-resizer:hover, .app.resizing .sidebar-resizer {
  background: color-mix(in srgb, var(--primary) 35%, transparent);
}

.app.resizing {
  cursor: col-resize;
  user-select: none;
}

.app.nav-rail .sidebar-resizer {
