}

.app.nav-rail .brand {
  justify-content: center;
  padding: 14px 0 10px;
}

.app.nav-rail .brand-name {
  display: none;
}

.app.nav-rail .brand-ico {
  width: 34px;
  height: 34px;
  padding: 7px;
  margin: 0;
  border: 1px solid var(--sidebar-active-line);
  border-radius: 8px;
  background: var(--brand-ico-bg);
}

.app.nav-rail .nav {
  padding: 6px 0;
  overflow: visible;
}

.app.nav-rail .nav-sub {
  display: none;
}

.app.nav-rail .nav-gap {
  height: 8px;
}

.app.nav-rail .nav-item {
  width: 36px;
  height: 36px;
  margin: 0 auto 4px;
  padding: 0;
  justify-content: center;
  border-radius: 8px;
}

.app.nav-rail .nav-item span {
  display: none;
}

.app.nav-rail .nav-item.scope-active {
  background: var(--sidebar-active);
  box-shadow: inset 0 0 0 1px var(--sidebar-active-line);
}

.rail-chev {
