}

.app.nav-rail .nav-item.flyout-open {
  background: var(--sidebar-hover);
}

.app.nav-rail .nav-item.flyout-open > svg:not(.rail-chev) {
  display: none;
}

.app.nav-rail .nav-item.flyout-open > .rail-chev {
  display: block;
}

.app.nav-rail .side-foot {
  flex-direction: column;
  gap: 6px;
  padding: 10px 0 12px;
}

.app.nav-rail .side-foot .bell-wrap {
  order: 1;
  margin-left: 0;
}

.app.nav-rail .side-foot #collapseBtn {
  order: 2;
  margin-left: 0;
}

.app.nav-rail .side-foot #collapseBtn svg {
  transform: rotate(180deg);
}

.app.nav-rail .side-foot .avatar-wrap {
  order: 3;
  margin-top: 4px;
}

.app.nav-rail .popover.up {
  bottom: 0;
  left: 46px;
}

.app.nav-rail .notif-panel {
  left: 46px;
}

/* Fenêtre qui s'ouvre au survol d'une icône du rail */
.rail-flyout {
  display: none;
  position: absolute;
  left: calc(var(--rail-w) + 2px);
  top: 0;
  z-index: 70;
  min-width: 230px;
  padding: 10px 8px;
  background: var(--surface-raised);
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  box-shadow: 0 8px 28px var(--shadow-fly);
}

.rail-flyout.open {
  display: block;
}

.rail-flyout::before {
  content: "";
  position: absolute;
  left: -10px;
  top: 0;
  bottom: 0;
  width: 10px;
} /* pont pour ne pas perdre le survol */
.fly-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 8px 8px;
  font-weight: 600;
}

.fly-head svg {
  width: 16px;
  height: 16px;
