  width: 100%;
  padding: 7px 10px;
  color: var(--text);
  border-radius: 6px;
  text-align: left;
}

.fly-sub .nav-item:hover {
  background: var(--hover);
}

.fly-sub .nav-item.active {
  background: var(--nav-active-fly);
