// chat-v1.7 (base : widget v6 du 2026-09-30) — copie de travail chat-version : fil de conversation + barre d'écriture (mode test : aucun SMS réel) + réponses marquées « lues » à l'ouverture + ligne en gras et point bleu pour les appels avec une réponse non lue + réponses non lues dans la cloche + lecture automatique quand la conversation est ouverte + relecture rapide tant qu'une conversation est ouverte (événements onChatOuvert / onChatFerme) + molette : le fil défile seul + mode sombre avec bascule en haut à droite (préférence mémorisée si le navigateur l'autorise) + bouton « Nouveau » (Envoi SMS) sur la page Appels Manqués
// Widget custom Appsmith — Portail SMS / Appels manqués (onglet JS)
// Toutes les données viennent de appsmith.model (propriété "Default Model").
// Pour brancher le backend plus tard : Default Model = {{ { ...ton objet, sms: getSms.data, appels: getAppels.data } }}

const $ = id => document.getElementById(id);
const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;"
})[c]);

// ---------- Mode sombre (chat-v1.6) ----------
// Clair par défaut. Le choix est mémorisé dans le navigateur (localStorage) si l'iframe du widget l'autorise ;
// sinon il est conservé jusqu'au rechargement de la page. Le thème est appliqué dès le chargement du script (pas de flash).
const THEME_CLE = "portail-sms-theme";
const theme = {
  actuel: "light",
  lire() {
    try {
      const v = window.localStorage.getItem(THEME_CLE);
      return v === "dark" || v === "light" ? v : null;
    } catch (e) {
      return null;
    }
  },
  ecrire(v) {
    try {
      window.localStorage.setItem(THEME_CLE, v);
    } catch (e) {/* mémorisation indisponible : le choix reste valable jusqu'au rechargement */}
  },
  appliquer(v) {
    this.actuel = v === "dark" ? "dark" : "light";
    document.documentElement.setAttribute("data-theme", this.actuel);
    const b = document.getElementById("themeBtn");
    if (b) {
      b.setAttribute("aria-checked", String(this.actuel === "dark"));
      b.title = this.actuel === "dark" ? "Revenir au mode clair" : "Passer en mode sombre";
    }
  },
  // Mémorisation dans Appsmith (appsmith.store, survit au rechargement) : le widget garde le choix dans le modèle
  // (themeChoisi) puis déclenche onChangerTheme = {{ storeValue("theme", Custom1.model.themeChoisi) }}.
  memoriser(v) {
    try {
      appsmith.updateModel({
        themeChoisi: v
      });
      appsmith.triggerEvent("onChangerTheme");
    } catch (e) {/* sans effet */}
  },
  // Au chargement : reprend le thème mémorisé par Appsmith (model.theme), une seule fois, et seulement si la personne
  // n'a pas déjà basculé pendant cette session (sinon l'ancienne valeur du modèle écraserait son choix).
  depuisModele() {
    if (this.synchronise || this.choixLocal) return;
    const t = window.appsmith && appsmith.model && appsmith.model.theme;
    if (t !== "dark" && t !== "light") return;
    this.synchronise = true;
    if (t !== this.actuel) this.appliquer(t);
    this.ecrire(t);
  },
  basculer() {
    const v = this.actuel === "dark" ? "light" : "dark";
    this.choixLocal = true;
    this.appliquer(v);
    this.ecrire(v);
    this.memoriser(v);
  },
  monter() {
    const zone = document.querySelector(".tools");
    if (!zone || document.getElementById("themeBtn")) return;
    const b = document.createElement("button");
    b.type = "button";
    b.id = "themeBtn";
    b.className = "theme-toggle";
    b.setAttribute("role", "switch");
    b.setAttribute("aria-label", "Mode sombre");
    b.innerHTML = '<span class="thumb">' + '<svg class="sun" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="3.4" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M10 2.5v2M10 15.5v2M2.5 10h2M15.5 10h2M4.7 4.7l1.4 1.4M13.9 13.9l1.4 1.4M4.7 15.3l1.4-1.4M13.9 6.1l1.4-1.4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>' + '<svg class="moon" viewBox="0 0 20 20" aria-hidden="true"><path d="M16.2 12.3A6.6 6.6 0 0 1 7.7 3.8a6.6 6.6 0 1 0 8.5 8.5Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>' + '</span>';
    b.addEventListener("click", () => this.basculer());
    zone.appendChild(b);
    this.appliquer(this.actuel);
  }
};
theme.appliquer(theme.lire() || "light");
const ICONS = {
