// ---------- Notifications (alertes calculées à partir des données) ----------
// Réglages : ce qui compte comme « notification ». À ajuster ici seulement.
const ALERTES = {
  joursAppels: 2,
  // appels manqués « Nouveau » des N derniers jours
  joursSms: 7,
  // SMS en échec des N derniers jours
  statutsSmsEchec: ["Erreur d'envoi", "Numéro Invalide", "Champs incomplets"]
};
function computeAlerts() {
  const m = model();
  const bureau = m.app && m.app.monBureau || "";
  const now = Date.now();
  const DAY = 864e5;
  const ms = iso => {
    if (!iso) return NaN;
    const s = String(iso);
    return new Date(s.length === 10 ? s + "T12:00:00" : s).getTime();
  };
  const out = [];
  (m.appels || []).forEach(r => {
    if (r.statut !== "Nouveau") return;
    if (bureau && r.bureau && r.bureau !== bureau) return;
    const t = ms(r.date);
    if (isNaN(t) || now - t > ALERTES.joursAppels * DAY) return;
    const qui = ["Anonyme", "Interne"].includes(r.appelant) ? esc(r.appelant) : fmtPhone(r.appelant);
    out.push({
      id: "appel:" + r.id,
      view: "appels",
      rowId: r.id,
      t,
      tone: "",
      title: r.type === "Message Vocal" ? "Nouveau message vocal" : "Nouvel appel manqué",
      sub: [qui, esc(r.bureau || ""), fmtLongDate(r.date) + (r.heure ? " " + esc(r.heure) : "")].filter(Boolean).join(" · ")
    });
  });
  (m.sms || []).forEach(r => {
    if (!ALERTES.statutsSmsEchec.includes(r.statut)) return;
    if (bureau && r.bureau && r.bureau !== bureau) return;
    let t = ms(r.dateEnvoi);
    if (isNaN(t)) t = ms(r.dateAjout);
    if (isNaN(t) || now - t > ALERTES.joursSms * DAY) return;
    out.push({
      id: "sms:" + r.id,
      view: "sms",
      rowId: r.id,
      t,
      tone: "red",
      title: "SMS non envoyé — " + r.statut,
      sub: [esc(r.client || "Sans nom"), fmtPhone(r.telephone)].filter(Boolean).join(" · ")
    });
  });
  // réponses de clients non lues : une alerte par conversation (client + bureau)
  const groupes = new Map();
  (Array.isArray(m.messages) ? m.messages : []).forEach(x => {
    if (x.sens !== "entrant" || x.luLe) return;
    if (bureau && x.bureau && x.bureau !== bureau) return;
    const k = x.numeroClient + "|" + x.bureau;
    const g = groupes.get(k) || {
      n: 0,
      t: 0,
      last: x
    };
    g.n += 1;
    const t = ms(x.creeLe);
    if (!isNaN(t) && t >= g.t) {
      g.t = t;
      g.last = x;
    }
    groupes.set(k, g);
  });
  groupes.forEach((g, k) => {
    const x = g.last;
    // l'appel le plus récent de cette conversation : c'est sa fiche que le clic ouvre (sans appel, pas d'alerte)
    const appel = (m.appels || []).filter(a => a.appelant === x.numeroClient && a.bureau === x.bureau).sort((a, b) => ms(b.date) - ms(a.date))[0];
    if (!appel) return;
    const extrait = String(x.texte || "").slice(0, 60) + (String(x.texte || "").length > 60 ? "…" : "");
    // l'identifiant change à chaque nouvelle réponse (dernier seq), pour qu'une nouvelle réponse sonne même si l'ancienne alerte a été lue
    out.push({
      id: "msg:" + k + ":" + x.seq,
      view: "appels",
      rowId: appel.id,
      t: g.t || ms(appel.date),
      tone: "",
      title: g.n > 1 ? g.n + " nouvelles réponses du client" : "Nouvelle réponse du client",
      sub: [fmtPhone(x.numeroClient), esc(x.bureau || ""), esc(extrait)].filter(Boolean).join(" · ")
    });
  });
  return out.sort((a, b) => b.t - a.t).slice(0, 100);
}
function renderNotifs() {
  const all = computeAlerts();
  const unread = all.filter(a => !state.notif.read.has(a.id));
  const n = unread.length;
  $("notifCount").textContent = n ? n > 99 ? "99+" : String(n) : "";
  $("notifCount").style.display = n ? "" : "none";
  if (!$("notifPanel").classList.contains("open")) return;
  const tab = state.notif.tab;
  const q = state.notif.q.trim().toLowerCase();
  document.querySelectorAll("[data-ntab]").forEach(b => b.classList.toggle("on", b.dataset.ntab === tab));
  const base = tab === "unread" ? unread : all.filter(a => state.notif.read.has(a.id));
  const list = base.filter(a => !q || (a.title + " " + a.sub).toLowerCase().includes(q));
  $("notifList").innerHTML = list.length ? list.map(a => `<button type="button" class="np-item" data-nid="${esc(a.id)}"><span class="np-dot ${a.tone}"></span><span class="np-txt"><b>${esc(a.title)}</b><small>${a.sub}</small></span></button>`).join("") : `<div class="np-empty">${tab === "unread" ? "Aucune notification non lue" : "Aucune notification lue"}</div>`;
  $("notifMarkAll").style.display = tab === "unread" && unread.length ? "" : "none";
}
function openAlert(id) {
  const a = computeAlerts().find(x => x.id === id);
  if (!a) return;
  state.notif.read.add(id);
  if (id.startsWith("msg:")) state.drawerFor = null;
  state.view = a.view;
  state.scope = "all";
  state.tabs.appels = "all";
  state.search = "";
  $("searchInput").value = "";
  state.filters[a.view].clear();
  state.checked.clear();
  state.selectedId = a.rowId;
  state.editing = false;
  state.creating = false;
  state.creatingEnvoi = false;
  state.errors = {};
  state.draft = null;
  $("notifPanel").classList.remove("open");
  render();
}
