// ---------- Barre d'écriture du chat (mode test : le message est enregistré, aucun SMS réel n'est envoyé) ----------
const GSM_BASE = "@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà";
const GSM_EXT = "^{}\\[~]|€";
// Estimation du nombre de SMS (le découpage réel dépend de l'opérateur).
function smsInfo(txt) {
  const nb = [...txt].length;
  if (!nb) return {
    nb: 0,
    segments: 0,
    gsm: true
  };
  let gsm = true,
    longueur = 0;
  for (const c of txt) {
    if (GSM_BASE.includes(c)) longueur += 1;else if (GSM_EXT.includes(c)) longueur += 2;else {
      gsm = false;
      break;
    }
  }
  if (gsm) return {
    nb,
    segments: longueur <= 160 ? 1 : Math.ceil(longueur / 153),
    gsm: true
  };
  return {
    nb,
    segments: nb <= 70 ? 1 : Math.ceil(nb / 67),
    gsm: false
  };
}
