// Crée le plan : même ligne que « + Ajouter plan » (page Planification SMS), même newRecord, même événement onAjouterSms.
function planifAjouterClic() {
  const r = rowsOf("appels").find(x => x.id === state.selectedId);
  if (!r || !chatPossible(r)) return;
  const digits = phoneDigits(r.appelant);
  if (digits.length !== 10 || !r.bureau) return;
  const d = state.planifDraft[r.id] || {};
  const telFmt = `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  // Le flux « Planification » refuse une ligne sans nom de client (« Champs incomplets ») : sans nom saisi, on met le numéro.
  const client = String(d.client !== undefined ? d.client : r.nomClient || "").trim() || telFmt;
  const perso = PLANIF_PERSO_ACTIF && d.messageId === PLANIF_PERSO;
  const messagePerso = perso ? String(d.messagePerso || "").trim() : "";
  const messageId = perso ? "" : d.messageId || "",
    dateEnvoi = d.dateEnvoi || "",
    heure = d.heure || "";
  const errors = {};
  if (!d.messageId) errors.messageId = "Champ obligatoire";else if (perso && !messagePerso) errors.messagePerso = "Écrivez le message à envoyer";
  if (!dateEnvoi) errors.dateEnvoi = "Champ obligatoire";else if (dateEnvoi < new Date().toLocaleDateString("sv-SE")) errors.dateEnvoi = "La date doit être aujourd'hui ou plus tard";
  if (!heure) errors.heure = "Champ obligatoire";
  state.planifErrors = errors;
  if (Object.keys(errors).length) {
    state.planifDraft[r.id] = {
      ...d,
      client: d.client !== undefined ? d.client : r.nomClient || ""
    };
    planifFormMaj(r);
    return;
  }
  const record = {
    id: "_new_" + Date.now(),
    client,
    telephone: telFmt,
    messageId,
    dateEnvoi,
    heure,
    ...(perso ? {
      message: "Message personnalisé",
      messagePerso
    } : {}),
    bureau: r.bureau,
    statut: "En attente",
    ajoutePar: model().app && model().app.utilisateur || "",
    dateAjout: new Date().toISOString()
  };
  delete state.planifDraft[r.id];
  state.planifErrors = {};
  appsmith.updateModel({
    sms: [...rowsOf("sms"), record],
    newRecord: {
      view: "sms",
      record
    }
  });
  appsmith.triggerEvent("onAjouterSms");
  planifMajListe(r);
  planifFormMaj(r);
  toast("Planification ajoutée — elle apparaît aussi dans la page Planification SMS");
}
