  const cases = (model().bureaux || []).map(b => `<label class="${choisis.has(b) ? "on" : ""}"><input type="checkbox" name="bureaux" value="${esc(b)}" ${choisis.has(b) ? "checked" : ""}><span class="box"></span><span>${esc(b)}</span></label>`).join("");
  $("drawerBody").innerHTML = `<form id="employeForm" class="edit-form" novalidate>` + `<label class="edit-field"><span class="k">Nom complet</span><input name="nom" type="text" value="${esc(nom)}" placeholder="Prénom Nom" autocomplete="off"></label>` + `<label class="edit-field ${e.email ? "has-error" : ""}"><span class="k">Courriel <span class="req">*</span></span><input name="email" type="email" value="${esc(email)}" placeholder="prenom@exemple.ca" autocomplete="off">` + `${e.email ? `<span class="err">${esc(e.email)}</span>` : `<span class="hint">Doit être identique à l'adresse du compte Appsmith de la personne.</span>`}</label>` + `<div class="edit-field ${e.role ? "has-error" : ""}"><span class="k">Rôle <span class="req">*</span></span><div class="emp-roles">${cartes}</div>${e.role ? `<span class="err">${esc(e.role)}</span>` : ""}</div>` + `<div class="edit-field ${e.bureaux ? "has-error" : ""}" id="empBureauxBloc" ${role === "direction" ? "hidden" : ""}><span class="k">Bureaux <span class="req">*</span></span><div class="emp-bureaux">${cases}</div>` + `${e.bureaux ? `<span class="err">${esc(e.bureaux)}</span>` : `<span class="hint">Cochez tous les bureaux où cette personne travaille.</span>`}</div>` + `<button type="submit" hidden></button></form>`;
