    : `<div class="np-empty">${tab === "unread" ? "Aucune notification non lue" : "Aucune notification lue"}</div>`;
  $("notifMarkAll").style.display = tab === "unread" && unread.length ? "" : "none";
}

function openAlert(id) {
  const a = computeAlerts().find((x) => x.id === id); if (!a) return;
  state.notif.read.add(id);
