const model = () => (window.appsmith && appsmith.model) || {};
// ---------- Accès par bureau : profil venu du JS Object (model().profil = { connu, role, tous, bureaux }) ----------
// « tous » : peut voir « Tous les bureaux » (direction, ou personne inconnue tant que ACCES_STRICT est false).
// Ce filtrage est une deuxième couche d'affichage ; le filtre réel viendra des requêtes SQL.
const profilAcces = () => model().profil || { connu: false, tous: true, bureaux: model().bureaux || [] };
const peutVoirTous = () => { const p = profilAcces(); return !!p.tous || (p.bureaux || []).length > 1; };
const libelleTous = () => (profilAcces().tous ? "Tous les bureaux" : "Tous mes bureaux");
function garderScopeAutorise() {
  if (state.view === "employes" && !peutGererEmployes()) { state.view = "modeles"; state.creatingEmploye = false; state.editing = false; state.selectedId = null; }
  const p = profilAcces(); if (p.tous || state.scope === "settings") return;
  const ok = p.bureaux || [];
  if (state.scope === "all" ? peutVoirTous() : ok.includes(state.scope)) return;
  state.scope = peutVoirTous() ? "all" : (ok[0] || "all");
  state.tabs.appels = "all"; state.selectedId = null; state.checked.clear();
}
const messagesAcces = () => {
  const tous = Array.isArray(model().messages) ? model().messages : [];
  const p = profilAcces();
  return p.tous ? tous : tous.filter((m) => (p.bureaux || []).includes(m.bureau));
};
// ---------- Employés (Paramètres > Employés) : réservé à la direction ----------
// Données : model().employes = lignes de chat.employes (une par personne ET par bureau ; la direction a bureau vide).
// Affichage : une ligne par personne (employesGroupes). Écritures : événements onEnregistrerEmploye / onSupprimerEmploye
// -> JS Object EmployeManager -> requêtes upsertEmploye / nettoyerEmploye / supprimerEmploye.
const DEMARRE = Date.now();
// model().chargement[vue] = true tant que la requête de cette vue n'a pas rendu ses données (voir getModel). Au-delà de 30 s, on arrête d'attendre.
const donneesEnChargement = (vue) => ((model().chargement || {})[vue] === true) && (Date.now() - (state.chargeDepuis || DEMARRE)) < 30000;
const donneesEnEchec = (vue) => ((model().chargement || {})[vue] === true) && (Date.now() - (state.chargeDepuis || DEMARRE)) >= 30000;
const peutGererEmployes = () => !!profilAcces().tous;   // direction (ou, pendant la transition, personne non encore inscrite)
const emailNorm = (e) => String(e || "").trim().toLowerCase();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const employesPlats = () => (Array.isArray(model().employes) ? model().employes : []);
function employesGroupes() {
  if (!peutGererEmployes()) return [];
  const moi = emailNorm((model().app || {}).monEmail);
  const ordre = model().bureaux || [];
  const map = new Map();
  employesPlats().forEach((l) => {
    const k = emailNorm(l.email); if (!k) return;
    let g = map.get(k);
    if (!g) { g = { id: k, email: k, nom: "", role: "employe", bureaux: [], creeLe: "" }; map.set(k, g); }
    if (l.role === "direction") g.role = "direction";
    if (l.nom && !g.nom) g.nom = l.nom;
    if (l.bureau && !g.bureaux.includes(l.bureau)) g.bureaux.push(l.bureau);
    if (l.creeLe && (!g.creeLe || l.creeLe < g.creeLe)) g.creeLe = l.creeLe;
  });
  return [...map.values()].map((g) => {
    const bureaux = g.role === "direction" ? [] : g.bureaux.sort((a, b) => ordre.indexOf(a) - ordre.indexOf(b));
    return {
      ...g, bureaux,
      nomAffiche: g.nom || g.email.split("@")[0],
      roleLibelle: g.role === "direction" ? "Direction" : "Employé",
      bureauxTxt: g.role === "direction" ? "Tous les bureaux" : bureaux.join(", "),
      estMoi: g.email === moi,
    };
  });
}

const rowsOf = (view) => {
  if (view === "employes") return employesGroupes();
  const rows = Array.isArray(model()[VIEWS[view].dataKey]) ? model()[VIEWS[view].dataKey] : [];
  const p = profilAcces();
  if (p.tous || view === "modeles") return rows;
  // Planification SMS : les plans sans bureau (importés d'Airtable, avant la migration) restent visibles
  // sous chaque bureau ; les plans créés dans Appsmith ont un bureau et sont filtrés comme le reste.
  return rows.filter((r) => (p.bureaux || []).includes(r.bureau) || (view === "sms" && !r.bureau));
};

// ---------- Modèles SMS par bureau (voir PLAN-modeles-sms-par-bureau.md) ----------
// défaut = ligne sans bureau ; texte personnalisé = ligne d'un bureau qui remplace un défaut (usage rempli, ou modeleDefaut = id du défaut) ;
// modèle de bureau = ligne d'un bureau sans usage ni modeleDefaut (ajouté par ce bureau). Le SQL (getConfigurationSms) ne renvoie à un employé
// que son bureau + les défauts non remplacés ; la direction reçoit tout.
const modeleEstDefaut = (r) => !r.bureau;
const modeleEstPerso = (r) => !!r.bureau && (!!r.usage || !!r.modeleDefaut);
const modeleCle = (m) => m.modeleDefaut || m.id;          // identifiant enregistré dans un plan : celui du DÉFAUT (le flux n8n cherche ensuite le texte du bureau)
const estEmployeSimple = () => !profilAcces().tous;       // employé d'un bureau (ni direction, ni personne non encore inscrite)
const modelesTous = () => (Array.isArray(model().modeles) ? model().modeles : []);
// Modèles MANUELS utilisables pour un bureau : ceux de ce bureau + les défauts qu'il n'a pas remplacés (jamais ceux d'un autre bureau).
function modelesManuelsPour(bureau) {
  const tous = modelesTous().filter((m) => !m.usage && m.titre);
  const remplaces = new Set(tous.filter((m) => m.bureau && m.bureau === bureau && m.modeleDefaut).map((m) => m.modeleDefaut));
  return tous.filter((m) => (m.bureau ? m.bureau === bureau : !remplaces.has(m.id)));
}
// Retrouve le modèle d'un plan (messageId = id du défaut ou id d'un modèle de bureau) : le texte du bureau d'abord.
function modeleDuPlan(messageId, bureau) {
  const tous = modelesTous();
  return (bureau && tous.find((m) => m.bureau === bureau && m.modeleDefaut === messageId)) ||
    tous.find((m) => m.id === messageId) || tous.find((m) => m.modeleDefaut === messageId);
}
// Le titre est en lecture seule dans « Modifier » : texte personnalisé (n'importe qui) ou défaut vu par un employé (« Modifier pour mon bureau »).
function titreModeleVerrouille() {
  const r = rowsOf("modeles").find((x) => x.id === state.selectedId);
  return !!r && (modeleEstPerso(r) || (estEmployeSimple() && modeleEstDefaut(r)));
}

function visibleCols() {
  return VIEWS[state.view].cols.filter((c) => !c.detailOnly && !(c.onlyAll && state.scope !== "all"));
}

// ---------- Onglets de filtre rapide (comme Airtable) ----------
// Réglage : « 7 jours » = aujourd'hui et les 6 jours précédents.
const TAB_RULES = { joursRecents: 7 };
const dayKey = (d) => d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
const dayKeyOf = (iso) => {
  if (!iso) return NaN;
  const s = String(iso); const d = new Date(s.length === 10 ? s + "T12:00:00" : s);
  return isNaN(d) ? NaN : dayKey(d);
};

// Onglets visibles selon la vue et le bureau (mêmes règles que les captures Airtable) :
//  - « Tous les bureaux » : All, Aujourd'hui, Non complété, 7 jours + un onglet par bureau
//  - un bureau : All, Aujourd'hui, 7 jours
//  - Planification SMS et Modèles SMS : aucun onglet
function tabsFor(view) {
  if (view === "employes") {
    // Employés : Tous, Direction, puis un onglet par bureau, chacun avec son nombre de personnes
    const g = employesGroupes();
    const n = (f) => g.filter(f).length;
    return [{ id: "all", label: `Tous (${g.length})` }, { id: "role:direction", label: `Direction (${n((x) => x.role === "direction")})` }]
      .concat((model().bureaux || []).map((b) => ({ id: "b:" + b, label: `${b} (${n((x) => x.bureaux.includes(b))})` })));
  }
  if (view !== "appels") return [];
  const all = state.scope === "all";
  return [{ id: "all", label: "All" }, { id: "today", label: "Aujourd'hui" }]
    .concat(all ? [{ id: "open", label: "Non complété" }] : [])
    .concat([{ id: "recent", label: TAB_RULES.joursRecents + " jours" }])
    .concat(all ? (model().bureaux || []).map((b) => ({ id: "b:" + b, label: b })) : []);
}
function activeTab(view) {
  const id = state.tabs[view];
  return tabsFor(view).some((t) => t.id === id) ? id : "all";
}
function matchTab(view, r) {
  const id = activeTab(view);
  if (id === "all") return true;
  if (view === "employes") {
    if (id === "role:direction") return r.role === "direction";
    if (id.startsWith("b:")) return r.bureaux.includes(id.slice(2));
    return true;
  }
  if (id === "open") return r.statut !== "Complété";
  if (id.startsWith("b:")) return r.bureau === id.slice(2);
  const k = dayKeyOf(r.date); if (isNaN(k)) return false;
  const now = new Date(); const today = dayKey(now);
  if (id === "today") return k === today;
  if (id === "recent") {
    const start = new Date(now); start.setDate(start.getDate() - (TAB_RULES.joursRecents - 1));
    return k >= dayKey(start) && k <= today;
  }
  return true;
}
function renderTabs() {
  const list = tabsFor(state.view); const box = $("viewTabs");
  const montrerNouveau = state.view === "appels" && state.scope !== "all";  // « + Nouveau » : seulement dans les pages de bureau
  const montrerAjoutEmploye = state.view === "employes";
  box.hidden = !list.length && !montrerNouveau && !montrerAjoutEmploye;
  if (!list.length && !montrerNouveau && !montrerAjoutEmploye) return;
  const on = activeTab(state.view);
  let html = list.map((t) =>
    `<button type="button" role="tab" class="view-tab ${t.id === on ? "on" : ""}" data-tab="${esc(t.id)}" aria-selected="${t.id === on}">${esc(t.label)}</button>`).join("");
  if (montrerNouveau) html += `<button type="button" class="btn-nouveau-envoi" data-nouveau-envoi="1">+ Nouveau</button>`;
  if (montrerAjoutEmploye) html += `<button type="button" class="btn-nouveau-envoi" data-ajout-employe="1">+ Ajouter un employé</button>`;
  box.innerHTML = html;
}

// Recherche : texte brut dans tous les champs ; en plus, si la saisie ressemble à un numéro
// (chiffres, espaces, parenthèses, tirets, +, point), on compare seulement les chiffres pour
// les champs téléphone, sans tenir compte du format ni du +1.
const PHONE_KEYS = ["appelant", "telephone", "numeroClient"];
const sansIndicatif = (d) => d.replace(/^1(?=\d{10}$)/, "");
function matchSearch(r, q) {
  if (!q) return true;
  const qd = sansIndicatif(String(q).replace(/\D/g, ""));
  const phoneLike = qd.length >= 3 && /^[\d\s()+.\-]+$/.test(q);
  return Object.entries(r).some(([k, x]) => {
    if (String(x ?? "").toLowerCase().includes(q)) return true;
    return phoneLike && PHONE_KEYS.includes(k) && sansIndicatif(String(x ?? "").replace(/\D/g, "")).includes(qd);
  });
}

function currentRows() {
  const v = VIEWS[state.view];
  const q = state.search.trim().toLowerCase();
  const f = state.filters[state.view];
  // Transition : tant qu'une ligne Planification SMS n'a pas de vrai bureau
  // assigné (cas de toutes les lignes créées par le compte générique avant
  // la mise en place du verrouillage par utilisateur connecté), on l'affiche
  // sous TOUS les bureaux plutôt que nulle part. Dès qu'une ligne a un vrai
  // bureau (nouvelles créations une fois l'app branchée), elle suit le
  // filtrage normal ci-dessous, sans besoin de retoucher ce code.
  const bureauInconnu = (r) => state.view === "sms" && !r.bureau;
  let rows = rowsOf(state.view).filter((r) =>
    (v.settings || state.scope === "all" || r.bureau === state.scope || bureauInconnu(r)) &&
    matchTab(state.view, r) &&
    (!f.size || f.has(r[v.filterKey])) &&
    matchSearch(r, q)
  );
  const s = state.sort[state.view];
  if (s) {
    const m = s.dir === "asc" ? 1 : -1;
    rows = [...rows].sort((a, b) => String(a[s.key] ?? "").localeCompare(String(b[s.key] ?? ""), "fr", { numeric: true }) * m);
  }
  return rows;
}

// ---------- Rendu ----------
// ---------- Menu replié (rail d'icônes) : fenêtre au survol + redimensionnement ----------
const railFly = { scope: null, timer: null };
const isRail = () => $("app").classList.contains("nav-rail");

function navigateTo(b) {
  const scopeChanged = b.dataset.scope !== undefined && b.dataset.scope !== state.scope;
  if (b.dataset.scope !== undefined) state.scope = b.dataset.scope;
  if (b.dataset.view) state.view = b.dataset.view;
  else if (state.scope === "settings") state.view = "modeles";
  else if (VIEWS[state.view].settings) state.view = "sms";
  if (scopeChanged) state.tabs.appels = "all";
  if (scopeChanged || b.dataset.view) { state.selectedId = null; state.checked.clear(); state.creatingEmploye = false; state.editing = false; }
  render();
}

function markFlyoutButton(scopeId) {
  document.querySelectorAll("#nav .nav-item[data-scope]").forEach((x) =>
    x.classList.toggle("flyout-open", !x.dataset.view && x.dataset.scope === scopeId));
}

function showFlyout(btn) {
  clearTimeout(railFly.timer);
  const id = btn.dataset.scope; railFly.scope = id;
  const label = id === "settings" ? "Parametres" : id === "all" ? libelleTous() : id;
  const icon = id === "settings" ? ICONS.tool : id === "all" ? ICONS.chart : ICONS.house;
  const items = id === "settings"
    ? [["modeles", VIEWS.modeles.title]].concat(peutGererEmployes() ? [["employes", VIEWS.employes.title]] : [])
    : [["appels", VIEWS.appels.title], ["sms", VIEWS.sms.title]];
  const fly = $("railFlyout");
  fly.innerHTML = `<div class="fly-head">${icon}<span>${esc(label)}</span></div><div class="fly-sub">` +
    items.map(([v, t]) => `<button type="button" class="nav-item ${state.scope === id && state.view === v ? "active" : ""}" data-scope="${esc(id)}" data-view="${v}">${t}</button>`).join("") + `</div>`;
  const appTop = $("app").getBoundingClientRect().top;
  const top = btn.getBoundingClientRect().top - appTop - 4;
  fly.style.top = Math.max(4, Math.min(top, $("app").clientHeight - 150)) + "px";
  fly.classList.add("open");
  markFlyoutButton(id);
}

function hideFlyout() {
  $("railFlyout").classList.remove("open");
  railFly.scope = null; markFlyoutButton(null);
}
const scheduleHideFlyout = () => { clearTimeout(railFly.timer); railFly.timer = setTimeout(hideFlyout, 180); };

function setRail(on) {
  $("app").classList.toggle("nav-rail", on);
  const label = on ? "Développer le menu de navigation" : "Réduire le menu de navigation";
  $("collapseBtn").setAttribute("aria-label", label); $("collapseBtn").title = label;
  hideFlyout(); renderNav();
}

function bindRail() {
  $("nav").addEventListener("mouseover", (e) => {
    if (!isRail()) return;
    const b = e.target.closest("button.nav-item[data-scope]");
    if (b && !b.dataset.view) showFlyout(b);
  });
  $("nav").addEventListener("mouseleave", scheduleHideFlyout);
  $("railFlyout").addEventListener("mouseenter", () => clearTimeout(railFly.timer));
  $("railFlyout").addEventListener("mouseleave", scheduleHideFlyout);
  $("railFlyout").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-view]"); if (!b) return;
    navigateTo(b); hideFlyout();
  });
  // Redimensionner la barre latérale en glissant son bord (double-clic = taille par défaut)
  const MIN = 190, MAX = 380, DEF = 236;
  const setW = (w) => $("app").style.setProperty("--side-w-user", Math.max(MIN, Math.min(MAX, Math.round(w))) + "px");
  $("sideResizer").addEventListener("mousedown", (e) => {
    if (isRail()) return;
    e.preventDefault();
    const app = $("app"); app.classList.add("resizing");
    const left = $("sidebar").getBoundingClientRect().left;
    const move = (ev) => setW(ev.clientX - left);
    const up = () => { app.classList.remove("resizing"); window.removeEventListener("mousemove", move); window.removeEventListener("mouseup", up); };
    window.addEventListener("mousemove", move); window.addEventListener("mouseup", up);
  });
  $("sideResizer").addEventListener("dblclick", () => setW(DEF));
}

function renderNav() {
  const scopes = (peutVoirTous() ? [{ id: "all", label: libelleTous(), icon: ICONS.chart }] : [])
    .concat((model().bureaux || []).map((b) => ({ id: b, label: b, icon: ICONS.house })));
  let html = "";
  scopes.forEach((s, i) => {
    const active = state.scope === s.id;
    html += `<button class="nav-item ${active ? "scope-active" : ""}" data-scope="${esc(s.id)}" ${isRail() ? `title="${esc(s.label)}" ` : ""}aria-label="${esc(s.label)}">${s.icon}${ICONS.chevR}<span>${esc(s.label)}</span></button>`;
    if (active) {
      html += `<div class="nav-sub">` + ["appels", "sms"].map((v) =>
