}

function renderGrid() {
  const v = VIEWS[state.view];
  const cols = visibleCols();
  const rows = currentRows();
  const s = state.sort[state.view];
  const w = (c) => state.widths[`${state.view}.${c.key}`] || c.w;

  $("cols").innerHTML = `<col style="width:40px">` + cols.map((c) => `<col style="width:${w(c)}px">`).join("");
  $("thead").innerHTML = `<tr><th class="gutter"></th>` + cols.map((c) => {
    const arrow = s && s.key === c.key ? (s.dir === "asc" ? ICONS.up : ICONS.down) : "";
    return `<th class="sortable" data-sort="${c.key}"><div class="th-in"><span class="lbl">${esc(c.label)}</span>${arrow}</div><span class="resizer" data-resize="${c.key}"></span></th>`;
  }).join("") + `</tr>`;

  const nonLus = state.view === "appels" ? chatNonLusParConversation() : new Map();
  $("tbody").innerHTML = rows.map((r) => {
    const cells = cols.map((c, i) => {
      const content = c.render ? c.render(r) : (r[c.key] ? esc(r[c.key]) : empty());
      const cls = [i === 0 ? "first" : "", c.wrap ? "wrap" : ""].join(" ").trim();
      return `<td class="${cls}"${i === 0 ? ` style="--bar:${v.bar(r)}"` : ""}>${c.wrap ? `<div class="clamp">${content}</div>` : content}</td>`;
    }).join("");
    const chk = state.checked.has(r.id) ? "checked" : "";
    const nl = nonLus.get(r.appelant + "|" + r.bureau) || 0;
    const pastille = nl ? `<span class="pastille-nonlu" title="${nl} réponse${nl > 1 ? "s" : ""} non lue${nl > 1 ? "s" : ""}"></span>` : "";
    const trCls = [state.selectedId === r.id ? "selected" : "", v.tall ? "tall" : "", nl ? "non-lu" : ""].join(" ").trim();
    return `<tr data-id="${esc(r.id)}" class="${trCls}"><td class="gutter">${pastille}<input type="checkbox" class="chk" data-chk="${esc(r.id)}" ${chk} aria-label="Sélectionner"></td>${cells}</tr>`;
  }).join("") + (v.addLabel ? `<tr class="add-row"><td class="gutter"></td><td colspan="${cols.length}"><button type="button" class="add-btn" data-add="1">+ ${esc(v.addLabel)}</button></td></tr>` : "");

  // Tableau vide : « Chargement des données… » tant que la requête n'a pas répondu (30 s au plus) ; au-delà, un message avec
  // un bouton « Actualiser » ; sinon « Aucun résultat ».
  const vide = rows.length === 0;
  $("empty").innerHTML = vide && donneesEnChargement(v.dataKey) ? "Chargement des données…"
    : vide && donneesEnEchec(v.dataKey) ? `Les données n'ont pas pu être chargées. <button type="button" class="add-btn" data-refresh="1">Actualiser</button>`
    : "Aucun résultat pour ces filtres.";
  $("empty").hidden = rows.length > 0;
  const [one, many] = v.unit;
  $("foot").textContent = `${rows.length} ${rows.length > 1 ? many : one}` + (state.checked.size ? ` · ${state.checked.size} sélectionné(s)` : "");
}

function renderFilterMenu() {
