    `<button type="button" class="pop-reset" data-filter-reset="1">Effacer les filtres</button>`;
}

// Nombre de réponses non lues par conversation (client + bureau), pour signaler les lignes d'appels dans la liste.
function chatNonLusParConversation() {
  const map = new Map();
  messagesAcces().forEach((m) => {
    if (m.sens === "entrant" && !m.luLe) {
      const k = m.numeroClient + "|" + m.bureau;
      map.set(k, (map.get(k) || 0) + 1);
    }
  });
  return map;
}

// ---------- Conversation (chat) : fil d'un client avec un bureau — chat-v1.0 ----------
const E164 = /^\+[0-9]{8,15}$/;
const AUTEURS_AUTO = {
  auto_planification: "Rappel automatique",
  auto_appel_manque: "Réponse automatique (appel manqué)",
  auto_message_vocal: "Réponse automatique (message vocal)",
  auto_bureau_ferme: "Réponse automatique (bureau fermé)",
};
// Pas de conversation pour « Anonyme », « Interne » ni pour un numéro qui n'est pas au format international.
const chatPossible = (r) => E164.test(String(r.appelant || "").trim());
// Une conversation = un numéro de client + un bureau (pas un appel).
const chatMessagesDe = (r) =>
  messagesAcces()
    .filter((m) => m.numeroClient === r.appelant && m.bureau === r.bureau);
function chatAuteur(m) {
  if (m.origine === "reponse_client") return "Client";
  if (m.origine === "chat_employe") return m.auteurNom || "Employé";
  return AUTEURS_AUTO[m.origine] || "Automatique";
}
function chatEtat(m) {
  if (m.sens === "entrant") return m.luLe ? "" : "Non lu";
  if (m.statut === "en_envoi") return "Envoi en cours…";
  if (m.statut === "erreur") return "Échec d'envoi" + (m.erreur ? " : " + m.erreur : "");
  return "Envoyé";
}
const chatJour = (ms) => new Date(ms).toLocaleDateString("fr-CA", { day: "numeric", month: "long", year: "numeric" });
function chatFilHTML(r) {
  const msgs = chatMessagesDe(r).map((m) => ({ t: new Date(m.creeLe).getTime(), seq: m.seq, m }));
  const appels = rowsOf("appels")
    .filter((a) => a.appelant === r.appelant && a.bureau === r.bureau)
    .map((a) => ({ t: new Date(a.date).getTime(), seq: -1, a }));
  const items = msgs.concat(appels).filter((x) => !isNaN(x.t)).sort((x, y) => (x.t - y.t) || (x.seq - y.seq));
  if (!items.length) return `<div class="chat-vide">Aucun message pour ce client avec ce bureau.</div>`;
  let jour = "", html = "";
  items.forEach((x) => {
    const j = chatJour(x.t);
    if (j !== jour) { jour = j; html += `<div class="chat-jour">${esc(j)}</div>`; }
    if (x.a) { html += `<div class="chat-evt"><span>📞 ${esc(x.a.type)} · ${fmtTime24(x.a.date)}</span></div>`; return; }
    const m = x.m;
    const cote = m.sens === "entrant" ? "gauche" : "droite";
    const cls = ["chat-bulle", AUTEURS_AUTO[m.origine] ? "auto" : "", m.statut === "erreur" ? "erreur" : "",
      m.statut === "en_envoi" ? "attente" : "", m.sens === "entrant" && !m.luLe ? "nonlu" : ""].filter(Boolean).join(" ");
    const etat = chatEtat(m);
    html += `<div class="chat-ligne ${cote}"><div class="${cls}">${esc(m.texte)}</div>` +
      `<div class="chat-meta">${esc(chatAuteur(m))} · ${fmtTime24(m.creeLe)}${etat ? " · " + esc(etat) : ""}</div></div>`;
  });
  // des appels mais aucun message : le dire clairement sous les événements d'appel
  if (!msgs.length) html += `<div class="chat-vide">Aucun message pour ce client avec ce bureau.</div>`;
  return html;
}
// ---------- Barre d'écriture du chat (mode test : le message est enregistré, aucun SMS réel n'est envoyé) ----------
const GSM_BASE = "@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà";
const GSM_EXT = "^{}\\[~]|€";
// Estimation du nombre de SMS (le découpage réel dépend de l'opérateur).
function smsInfo(txt) {
  const nb = [...txt].length;
  if (!nb) return { nb: 0, segments: 0, gsm: true };
  let gsm = true, longueur = 0;
  for (const c of txt) {
    if (GSM_BASE.includes(c)) longueur += 1;
    else if (GSM_EXT.includes(c)) longueur += 2;
    else { gsm = false; break; }
  }
  if (gsm) return { nb, segments: longueur <= 160 ? 1 : Math.ceil(longueur / 153), gsm: true };
  return { nb, segments: nb <= 70 ? 1 : Math.ceil(nb / 67), gsm: false };
}
function chatSaisieHTML(r) {
  const modeles = modelesManuelsPour(r.bureau).filter((x) => x.message);
  return `<div class="chat-saisie">` +
    (modeles.length ? `<select id="chatModele" aria-label="Insérer un modèle"><option value="">Insérer un modèle…</option>${modeles.map((x) => `<option value="${esc(x.id)}">${esc(x.titre)}</option>`).join("")}</select>` : "") +
    `<textarea id="chatTexte" rows="3" maxlength="1000" placeholder="Écrire un message au client…">${esc(state.brouillons[r.id] || "")}</textarea>` +
    `<div class="chat-saisie-pied"><span id="chatCompteur" class="chat-compteur"></span><button type="button" class="btn primary" id="chatEnvoyer" title="Envoyer (Ctrl + Entrée)" disabled>Envoyer</button></div>` +
    `</div>`;
}
function chatSaisieMaj() {
  const zone = $("chatTexte"); if (!zone) return;
  const info = smsInfo(zone.value);
  $("chatCompteur").textContent = info.nb
    ? `${info.nb} caractère${info.nb > 1 ? "s" : ""} · ${info.segments} SMS${info.gsm ? "" : " (caractères spéciaux : SMS plus courts)"}`
    : "0 caractère";
  $("chatEnvoyer").disabled = !zone.value.trim();
}
// Redessine seulement le fil (pas la zone d'écriture) : le texte tapé et le curseur ne sont jamais perdus à la relecture automatique.
function chatMajFil(r) {
  const fil = $("chatFil"); if (!fil) return;
  const enBas = fil.scrollHeight - fil.scrollTop - fil.clientHeight < 40;
  const haut = fil.scrollTop;
  fil.innerHTML = chatFilHTML(r);
  fil.scrollTop = enBas ? fil.scrollHeight : haut;
  const non = chatMessagesDe(r).filter((m) => m.sens === "entrant" && !m.luLe).length;
  const cpt = $("drawerBody").querySelector(".chat-count");
  if (cpt) cpt.textContent = non ? non + (non > 1 ? " non lus" : " non lu") : "";
  const onglets = $("drawerBody").querySelector(".drawer-tabs");
  if (onglets) onglets.outerHTML = chatOngletsHTML(r);
  const cle = r.appelant + "|" + r.bureau;
  const recent = state.luRecent && state.luRecent.cle === cle && Date.now() - state.luRecent.t < 10000;
  if (non && !recent && !document.hidden) { state.luRecent = { cle, t: Date.now() }; chatMarquerLu(r); }
}
function envoyerMessageChat(r, texte) {
  const app = model().app || {};
  const maintenant = new Date().toISOString();
  const nouveau = { appelId: r.id, bureau: r.bureau, numeroClient: r.appelant, texte, creeLe: maintenant };
  // copie locale affichée tout de suite (« envoi en cours ») ; la vraie ligne arrive à la relecture suivante
  const local = {
    seq: 1e15 + Date.now(), id: "_local_" + Date.now(), creeLe: maintenant, bureau: r.bureau, numeroBureau: "", numeroClient: r.appelant,
    sens: "sortant", origine: "chat_employe", texte, statut: "en_envoi", erreur: null,
    auteurNom: (app.utilisateur || "Employé") + " (test)", auteurEmail: app.monEmail || "", modeleTitre: null, appelId: r.id,
    luLe: null, luPar: null, expediteur: "", destinataire: "",
  };
  appsmith.updateModel({
    messages: [...(Array.isArray(model().messages) ? model().messages : []), local],
    nouveauMessage: nouveau,
  });
  appsmith.triggerEvent("onEnvoyerMessage");
  render();
}
// Marque comme lues les réponses du client quand on ouvre la conversation : copie locale tout de suite + événement vers Appsmith.
function chatMarquerLu(r) {
  const non = chatMessagesDe(r).filter((m) => m.sens === "entrant" && !m.luLe);
  if (!non.length) return;
  const maintenant = new Date().toISOString();
  const app = model().app || {};
  const tous = Array.isArray(model().messages) ? model().messages : [];
  appsmith.updateModel({
    messages: tous.map((m) => (non.includes(m) ? { ...m, luLe: maintenant, luPar: app.monEmail || "" } : m)),
    conversationLue: { numeroClient: r.appelant, bureau: r.bureau },
  });
  appsmith.triggerEvent("onOuvrirConversation");
  render();
}
// Relecture rapide : prévient Appsmith quand une conversation est affichée (onChatOuvert) ou ne l'est plus (onChatFerme).
function chatSuivi() {
  const r = state.view === "appels" && !state.editing && !state.creating ? rowsOf("appels").find((x) => x.id === state.selectedId) : null;
  const veut = !!(r && chatPossible(r) && state.drawerTab === "chat" && $("drawer").classList.contains("open"));
  if (veut !== !!state.chatOuvert) {
    state.chatOuvert = veut;
    appsmith.triggerEvent(veut ? "onChatOuvert" : "onChatFerme");
  }
}
function chatEnvoyerClic() {
  const zone = $("chatTexte"); if (!zone) return;
  const texte = zone.value.trim(); if (!texte) return;
  const r = rowsOf("appels").find((x) => x.id === state.selectedId);
  if (!r || !chatPossible(r)) return;
  state.brouillons[r.id] = ""; zone.value = ""; chatSaisieMaj();
  envoyerMessageChat(r, texte);
}

// ---------- Onglet « Planification » du panneau d'un appel (planif-v1.0) ----------
