function planifItemHTML(p) {
  const titre = p.messagePerso ? "Message personnalisé" : (p.message || (modeleDuPlan(p.messageId, p.bureau) || {}).titre);
  return `<div class="planif-item">` +
    `<div class="planif-ligne"><span class="planif-date">${p.dateEnvoi ? fmtLongDate(p.dateEnvoi) : empty("Sans date")}</span>` +
