    `<div class="planif-ligne">${titre ? `<span class="tag">${esc(titre)}</span>` : empty("Sans modèle")}` +
    `<span class="planif-qui">${p.client ? esc(p.client) : ""}</span></div>` +
    `${p.messagePerso ? `<div class="planif-texte">${esc(p.messagePerso)}</div>` : ""}</div>`;
