const PLANIF_PERSO = "__perso__";   // valeur de la liste « Message à envoyer » = message écrit à la main pour ce client
// Interrupteur : tant que la base n'a pas de colonne pour le texte personnalisé (étapes 1 à 4 du plan), l'option reste masquée.
// Pour la réactiver (étape 5) : mettre true.
const PLANIF_PERSO_ACTIF = false;
function planifCompteurTxt(txt) {
  const info = smsInfo(String(txt || ""));
  return info.nb ? `${info.nb} caractère${info.nb > 1 ? "s" : ""} · ${info.segments} SMS${info.gsm ? "" : " (caractères spéciaux : SMS plus courts)"}` : "";
}
const planifCompteTxt = (n) => (n ? n + (n > 1 ? " plans" : " plan") : "");
const planifListeHTML = (plans) => plans.length
  ? `<div class="planif-liste">${plans.map(planifItemHTML).join("")}</div>`
  : `<div class="chat-vide">Aucun SMS planifié pour ce client avec ce bureau.</div>`;
function planifPanneauHTML(r) {
  const plans = planifsDe(r);
  return `<div class="chat planif"><div class="chat-titre"><span>${fmtPhone(r.appelant)} · ${esc(r.bureau || "")}</span>` +
    `<span class="chat-count" id="planifCompte">${planifCompteTxt(plans.length)}</span></div>` +
    `<div class="chat-fil" id="planifListe">${planifListeHTML(plans)}</div>` +
    `<div class="chat-saisie planif-form" id="planifFormZone">${planifFormHTML(r)}</div></div>`;
}
// Zone d'ajout (même principe que la zone d'écriture du chat) : les modèles viennent de Paramètres > Modèles SMS (model().modeles).
function planifFormHTML(r) {
  if (phoneDigits(r.appelant).length !== 10) {
    return `<div class="chat-vide">Planification impossible : ce numéro n'est pas un numéro nord-américain à 10 chiffres.</div>`;
  }
  if (!r.bureau) return `<div class="chat-vide">Planification impossible : cet appel n'a pas de bureau.</div>`;
  const d = state.planifDraft[r.id] || {};
  const err = state.planifErrors || {};
  const modeles = modelesManuelsPour(r.bureau).filter((x) => x.message);
  const client = d.client !== undefined ? d.client : (r.nomClient || "");
  const msg = modeles.find((m) => modeleCle(m) === d.messageId);
  const aujourdhui = new Date().toLocaleDateString("sv-SE");
  const champ = (key, label, input, requis = true) =>
    `<label class="edit-field ${err[key] ? "has-error" : ""}"><span class="k">${label}${requis ? ' <span class="req">*</span>' : ""}</span>${input}${err[key] ? `<span class="err">${esc(err[key])}</span>` : ""}</label>`;
  const heures = ["AM (8h00)", "PM (Midi)"];
  const perso = PLANIF_PERSO_ACTIF && d.messageId === PLANIF_PERSO;
  return `<div class="edit-form">` +
    champ("client", "Nom du client (facultatif)", `<input type="text" data-planif="client" value="${esc(client)}" placeholder="Sinon : ${esc(fmtPhone(r.appelant))}">`, false) +
    champ("messageId", "Message à envoyer",
      `<select data-planif="messageId"><option value="">— Choisir —</option>${modeles.map((m) => `<option value="${esc(modeleCle(m))}" ${modeleCle(m) === d.messageId ? "selected" : ""}>${esc(m.titre)}</option>`).join("")}` +
      `${PLANIF_PERSO_ACTIF ? `<option value="${PLANIF_PERSO}" ${perso ? "selected" : ""}>✏️ Écrire un message personnalisé…</option>` : ""}</select>`) +
    `<div class="msg-preview planif-apercu" id="planifApercu">${msg ? esc(msg.message) : ""}</div>` +
    `<div id="planifPersoZone" style="display:${perso ? "block" : "none"}">` +
      champ("messagePerso", "Message personnalisé (pour ce client seulement)",
        `<textarea data-planif="messagePerso" rows="4" maxlength="1000" placeholder="Écrire le SMS à envoyer à ce client…">${esc(d.messagePerso || "")}</textarea>`) +
      `<div id="planifCompteur" class="chat-compteur">${planifCompteurTxt(d.messagePerso)}</div>` +
    `</div>` +
    `<div class="planif-duo">` +
      champ("dateEnvoi", "Date d'envoi", `<input type="date" data-planif="dateEnvoi" min="${aujourdhui}" value="${esc(d.dateEnvoi || "")}">`) +
      champ("heure", "Heure", `<select data-planif="heure"><option value="">— Choisir —</option>${heures.map((h) => `<option value="${esc(h)}" ${h === d.heure ? "selected" : ""}>${esc(h)}</option>`).join("")}</select>`) +
    `</div>` +
    `<button type="button" class="btn primary" id="planifAjouter">Planifier le SMS</button>` +
    `</div>`;
}
function planifMajListe(r) {
  const liste = $("planifListe"); if (!liste) return;
  const plans = planifsDe(r);
  liste.innerHTML = planifListeHTML(plans);
  const cpt = $("planifCompte"); if (cpt) cpt.textContent = planifCompteTxt(plans.length);
  const onglets = $("drawerBody").querySelector(".drawer-tabs");
  if (onglets) onglets.outerHTML = chatOngletsHTML(r);
}
function planifFormMaj(r) {
  const zone = $("planifFormZone"); if (zone) zone.innerHTML = planifFormHTML(r);
}
// Mémorise la saisie (par appel) pour qu'une relecture du modèle ne l'efface pas ; affiche le texte du modèle choisi.
function planifSaisie(e) {
  const key = e.target && e.target.dataset ? e.target.dataset.planif : null; if (!key) return;
  const r = rowsOf("appels").find((x) => x.id === state.selectedId); if (!r) return;
  const d = (state.planifDraft[r.id] = state.planifDraft[r.id] || {});
  d[key] = e.target.value;
  if (key === "messageId") {
    const m = modelesManuelsPour(r.bureau).find((x) => modeleCle(x) === e.target.value);
    const ap = $("planifApercu"); if (ap) ap.textContent = m && m.message ? m.message : "";
    const zone = $("planifPersoZone"); if (zone) zone.style.display = e.target.value === PLANIF_PERSO ? "block" : "none";
  }
  if (key === "messagePerso") { const c = $("planifCompteur"); if (c) c.textContent = planifCompteurTxt(e.target.value); }
}
// Crée le plan : même ligne que « + Ajouter plan » (page Planification SMS), même newRecord, même événement onAjouterSms.
function planifAjouterClic() {
  const r = rowsOf("appels").find((x) => x.id === state.selectedId);
  if (!r || !chatPossible(r)) return;
  const digits = phoneDigits(r.appelant);
  if (digits.length !== 10 || !r.bureau) return;
  const d = state.planifDraft[r.id] || {};
  const telFmt = `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  // Le flux « Planification » refuse une ligne sans nom de client (« Champs incomplets ») : sans nom saisi, on met le numéro.
  const client = String(d.client !== undefined ? d.client : (r.nomClient || "")).trim() || telFmt;
  const perso = PLANIF_PERSO_ACTIF && d.messageId === PLANIF_PERSO;
  const messagePerso = perso ? String(d.messagePerso || "").trim() : "";
  const messageId = perso ? "" : (d.messageId || ""), dateEnvoi = d.dateEnvoi || "", heure = d.heure || "";
  const errors = {};
  if (!d.messageId) errors.messageId = "Champ obligatoire";
  else if (perso && !messagePerso) errors.messagePerso = "Écrivez le message à envoyer";
  if (!dateEnvoi) errors.dateEnvoi = "Champ obligatoire";
  else if (dateEnvoi < new Date().toLocaleDateString("sv-SE")) errors.dateEnvoi = "La date doit être aujourd'hui ou plus tard";
  if (!heure) errors.heure = "Champ obligatoire";
  state.planifErrors = errors;
  if (Object.keys(errors).length) { state.planifDraft[r.id] = { ...d, client: d.client !== undefined ? d.client : (r.nomClient || "") }; planifFormMaj(r); return; }

  const record = {
    id: "_new_" + Date.now(),
    client,
    telephone: telFmt,
    messageId, dateEnvoi, heure,
    ...(perso ? { message: "Message personnalisé", messagePerso } : {}),
    bureau: r.bureau,
    statut: "En attente",
    ajoutePar: (model().app && model().app.utilisateur) || "",
    dateAjout: new Date().toISOString(),
  };
  delete state.planifDraft[r.id]; state.planifErrors = {};
  appsmith.updateModel({
    sms: [...rowsOf("sms"), record],
    newRecord: { view: "sms", record },
  });
  appsmith.triggerEvent("onAjouterSms");
  planifMajListe(r); planifFormMaj(r);
  toast("Planification ajoutée — elle apparaît aussi dans la page Planification SMS");
}

