    editBtn.innerHTML = "Créer";
    $("drawerDelete").hidden = true;
    d.classList.add("open"); d.setAttribute("aria-hidden", "false");
    d.classList.remove("large");
    renderEnvoiSmsForm();
    return;
  }
  if (state.creatingEmploye) {
    $("drawerTitle").textContent = "Nouvel employé";
    editBtn.hidden = false;
    editBtn.className = "btn-edit btn-edit-primary";
    editBtn.setAttribute("aria-label", "Ajouter");
    editBtn.innerHTML = "Ajouter";
    $("drawerDelete").hidden = true;
    d.classList.add("open"); d.setAttribute("aria-hidden", "false");
    d.classList.remove("large");
    renderEmployeForm("create", null);
    return;
  }
  if (state.creating) {
    const v = VIEWS[state.view];
    $("drawerTitle").textContent = "Nouveau " + v.unit[0];
    editBtn.hidden = false;
    editBtn.className = "btn-edit btn-edit-primary";
    editBtn.setAttribute("aria-label", "Créer");
    editBtn.innerHTML = "Créer";
    $("drawerDelete").hidden = true;
    d.classList.add("open"); d.setAttribute("aria-hidden", "false");
    d.classList.remove("large");
    renderCreateForm();
    return;
  }
  const r = rowsOf(state.view).find((x) => x.id === state.selectedId);
  if (!r) { d.classList.remove("open"); d.setAttribute("aria-hidden", "true"); state.drawerFor = null; return; }
  const v = VIEWS[state.view];
  const title = state.view === "sms" ? (r.client || "SMS sans nom")
    : state.view === "modeles" ? (r.titre || "Modèle sans titre")
    : state.view === "employes" ? r.nomAffiche : `Appel du ${fmtLongDate(r.date)}`;
  const pourMonBureau = state.view === "modeles" && estEmployeSimple() && modeleEstDefaut(r);   // employé qui modifie un texte par défaut = version de son bureau
  $("drawerTitle").textContent = state.editing ? `${pourMonBureau ? "Modifier pour mon bureau" : "Modifier"} · ${title}` : title;
  if (state.editing) {
    editBtn.hidden = false;
    editBtn.className = "btn-edit btn-edit-primary";
    editBtn.setAttribute("aria-label", pourMonBureau ? "Enregistrer pour mon bureau" : "Enregistrer");
    editBtn.innerHTML = pourMonBureau ? "Enregistrer pour mon bureau" : "Enregistrer";
  } else {
    editBtn.hidden = !EDIT[state.view] || (state.view === "employes" && r.estMoi);   // son propre accès ne se modifie pas ici
    editBtn.className = "btn-edit";
    const libModifier = (state.view === "modeles" && estEmployeSimple() && modeleEstDefaut(r)) ? "Modifier pour mon bureau" : "Modifier";
    editBtn.setAttribute("aria-label", libModifier);
    editBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 20 20" aria-hidden="true"><path d="M13.6 3.6a2 2 0 0 1 2.8 2.8L7 15.8l-3.5.7.7-3.5 9.4-9.4Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>' + libModifier;
  }
  $("drawerDelete").hidden = !v.deleteEvent || (state.view === "employes" && r.estMoi);   // modèles : la corbeille reste toujours visible, chaque clic donne une action ou un message
  d.classList.add("open"); d.setAttribute("aria-hidden", "false");
  if (state.editing) { if (state.view === "employes") renderEmployeForm("edit", r); else renderEditForm(r); return; }
  let fields = v.cols.map((c) => `<div class="field"><div class="k">${esc(c.label)}</div><div class="v ${c.wrap ? "msg-preview" : ""}">${c.render ? c.render(r) : (r[c.key] ? esc(r[c.key]) : empty())}</div></div>`).join("");
  if (state.view === "sms") {
    const tpl = (model().modeles || []).find((m) => m.titre === r.message);
    if (tpl && tpl.message) fields += `<div class="field"><div class="k">Texte du SMS (modèle « ${esc(tpl.titre)} »)</div><div class="v msg-preview">${esc(tpl.message)}</div></div>`;
  }
  if (state.view === "modeles" && estEmployeSimple() && modeleEstDefaut(r)) {
    injectEmployeStyles();
    fields += `<div class="note-info">Texte par défaut : seule la direction peut le modifier. « Modifier pour mon bureau » crée la version de votre bureau.</div>`;
  }
  const incomplete = state.view === "sms" && r.statut === "Champs incomplets";
  if (state.view === "employes") {
    injectEmployeStyles();
    if (r.estMoi) fields += `<div class="note-info">C'est votre compte. Pour éviter de vous retirer l'accès par erreur, une autre personne de la direction doit le modifier.</div>`;
    else fields += `<div class="note-info">Cette personne doit avoir un compte Appsmith avec exactement cette adresse courriel pour se connecter.</div>`;
  }
  let corps = fields + (incomplete ? `<div class="warn">Des champs obligatoires sont manquants : complétez-les avant l'envoi.</div>` : "");
  const memeAppel = state.drawerFor === r.id;
  if (state.view === "appels") {
    const possible = chatPossible(r);
    if (!memeAppel) { state.drawerFor = r.id; state.drawerTab = possible ? "chat" : "details"; }
    // même appel, déjà sur la conversation : on ne redessine que le fil (la zone d'écriture reste intacte)
    if (possible && memeAppel && state.drawerTab === "chat" && $("chatFil")) { chatMajFil(r); d.classList.add("large"); return; }
    // même appel, déjà sur « Planification » : on ne rafraîchit que la liste (le formulaire en cours de saisie reste intact)
    if (possible && memeAppel && state.drawerTab === "planif" && $("planifListe")) { planifMajListe(r); d.classList.add("large"); return; }
    if (!possible) {
      corps = `<div class="chat-vide">Pas de conversation possible : l'appelant est « ${esc(r.appelant || "inconnu")} » (numéro anonyme, interne ou invalide).</div>` + fields;
    } else {
      corps = chatOngletsHTML(r) + (state.drawerTab === "chat" ? chatPanneauHTML(r) : state.drawerTab === "planif" ? planifPanneauHTML(r) : fields);
    }
  }
  const filAvant = $("chatFil");
  const enBas = !filAvant || filAvant.scrollHeight - filAvant.scrollTop - filAvant.clientHeight < 40;
  const hautAvant = filAvant ? filAvant.scrollTop : 0;
  $("drawerBody").innerHTML = corps;
  d.classList.toggle("large", state.view === "appels");
  chatSaisieMaj();
  if (state.view === "appels" && state.drawerTab === "chat" && !memeAppel && chatPossible(r)) setTimeout(() => chatMarquerLu(r), 0);
  const filApres = $("chatFil");
  if (filApres) filApres.scrollTop = (enBas || !memeAppel) ? filApres.scrollHeight : hautAvant;
  $("drawerFoot").innerHTML = state.view === "sms"
    ? `<button class="btn" type="button" data-close="1">Fermer</button><button class="btn primary" type="button" data-send="${esc(r.id)}" ${incomplete || r.statut === "Envoyé" ? "disabled" : ""}>Envoyer maintenant</button>`
    : (state.view === "modeles" && modeleEstPerso(r)
      ? `<button class="btn" type="button" data-close="1">Fermer</button><button class="btn" type="button" data-retablir="${esc(r.id)}">Rétablir le défaut</button>`
      : `<button class="btn" type="button" data-close="1">Fermer</button>`);
  d.classList.add("open"); d.setAttribute("aria-hidden", "false");
}

// Rendu partagé des champs de formulaire (utilisé pour "Modifier" ET "Nouveau").
// getVal(f) renvoie la valeur à afficher pour un champ donné. mode "create"
// affiche les champs marqués lockOnCreate en lecture seule, pré-remplis
// automatiquement (ex: Bureau, déterminé par qui est connecté) — impossible
// à changer par erreur au moment de la création.
function fieldsFormHTML(getVal, mode) {
  return EDIT[state.view].map((f) => {
    const val = getVal(f);
    const err = state.errors[f.key];
    const req = f.required ? ' <span class="req">*</span>' : "";
    const verrou = mode === "edit" && state.view === "modeles" && f.key === "titre" && titreModeleVerrouille();
    let input;
    if (mode === "create" && f.lockOnCreate) {
      input = `<input type="hidden" name="${f.key}" value="${esc(val)}">` +
        `<div class="v" style="padding:8px 10px;border:1px solid var(--line-strong);border-radius:6px;background:var(--hover);">${val ? esc(val) : empty("Non déterminé — voir un administrateur")}</div>`;
    } else if (f.type === "select") {
      const rawOpts = f.options();
      const opts = rawOpts.map((o) => (o && typeof o === "object") ? o : { value: o, label: o });
      const hasVal = opts.some((o) => o.value === val);
      const all = val && !hasVal ? [{ value: val, label: val }, ...opts] : opts;
      input = `<select name="${f.key}"><option value="">— Choisir —</option>${all.map((o) => `<option value="${esc(o.value)}" ${o.value === val ? "selected" : ""}>${esc(o.label)}</option>`).join("")}</select>`;
    } else if (f.type === "textarea") {
      input = `<textarea name="${f.key}" rows="6">${esc(val)}</textarea>`;
    } else {
      input = `<input name="${f.key}" type="${f.type === "tel" ? "tel" : f.type}" value="${esc(val)}" ${f.type === "tel" ? 'placeholder="(819) 555-1234"' : ""} ${verrou ? 'readonly style="opacity:.7"' : ""}>`;
    }
    return `<label class="edit-field ${err ? "has-error" : ""}"><span class="k">${esc(f.label)}${req}</span>${input}${err ? `<span class="err">${esc(err)}</span>` : ""}</label>`;
  }).join("");
}

function renderEditForm(r) {
  const getVal = (f) => {
    const fromDraft = state.draft && f.key in state.draft;
    const val = fromDraft ? state.draft[f.key] : (r[f.key] ?? "");
    return f.type === "tel" && val && !fromDraft ? fmtPhone(val) : val;
  };
  $("drawerBody").innerHTML = `<form id="editForm" class="edit-form" novalidate>${fieldsFormHTML(getVal, "edit")}<button type="submit" hidden></button></form>`;
  $("drawerFoot").innerHTML = "";
  const first = $("drawerBody").querySelector("input, select, textarea");
  if (first) first.focus();
}

// Panneau "Nouveau" — formulaire vierge ouvert par le bouton "+ Ajouter...".
// Les champs lockOnCreate (ex: Bureau) sont pré-remplis avec les valeurs de
// l'utilisateur connecté (model().app.monBureau) et non modifiables.
function renderCreateForm() {
  const getVal = (f) => {
    if (state.draft && f.key in state.draft) return state.draft[f.key];
    if (f.lockOnCreate && f.key === "bureau") {
      // Priorité 1 : le bureau dans lequel on navigue déjà (le plus fiable —
      // on vient justement de cliquer un bureau précis > Planification SMS > +).
      if (state.scope !== "all" && state.scope !== "settings") return state.scope;
      // Priorité 2 (secours, cas "Tous les bureaux") : déduit de qui est connecté.
      return (model().app && model().app.monBureau) || "";
    }
    return "";
  };
  $("drawerBody").innerHTML = `<form id="createForm" class="edit-form" novalidate>${fieldsFormHTML(getVal, "create")}<button type="submit" hidden></button></form>`;
  $("drawerFoot").innerHTML = "";
  const first = $("drawerBody").querySelector("input, select, textarea");
  if (first) first.focus();
}

// ---------- Création « Envoi SMS » depuis le bouton « Nouveau » (Appels Manqués) ----------
// Formulaire dédié (pas le pipeline générique EDIT.appels/renderCreateForm/saveCreate,
// qui formate les téléphones en (819) 555-1234 — ici il faut le format +1XXXXXXXXXX
// attendu par test_appels_manques.appelant et par le E164 du chat).
const ENVOI_SMS_FIELDS = [
  { key: "telephone", label: "Numéro de téléphone", type: "tel", required: true },
  { key: "nomClient", label: "Nom du client", type: "text", required: false },
];
function detectBureauPourCreation() {
  // Même logique de priorité que renderCreateForm() pour Planification SMS :
  // 1) le bureau dans lequel on navigue déjà, 2) celui de l'utilisateur connecté.
  if (state.scope !== "all" && state.scope !== "settings") return state.scope;
  return (model().app && model().app.monBureau) || "";
}
function renderEnvoiSmsForm() {
  const bureau = detectBureauPourCreation();
  const getVal = (f) => (state.draft && f.key in state.draft) ? state.draft[f.key] : "";
  const champs = ENVOI_SMS_FIELDS.map((f) => {
    const val = getVal(f);
    const err = state.errors[f.key];
    const req = f.required ? ' <span class="req">*</span>' : "";
    const input = `<input name="${f.key}" type="${f.type === "tel" ? "tel" : f.type}" value="${esc(val)}" ${f.type === "tel" ? 'placeholder="(819) 555-1234"' : ""}>`;
    return `<label class="edit-field ${err ? "has-error" : ""}"><span class="k">${esc(f.label)}${req}</span>${input}${err ? `<span class="err">${esc(err)}</span>` : ""}</label>`;
  }).join("");
  const bureauLigne = `<div class="field"><div class="k">Bureau</div><div class="v" style="padding:8px 10px;border:1px solid var(--line-strong);border-radius:6px;background:var(--hover);">${bureau ? esc(bureau) : empty("Non déterminé — voir un administrateur")}</div></div>`;
  $("drawerBody").innerHTML = `<form id="envoiSmsForm" class="edit-form" novalidate>${champs}${bureauLigne}<button type="submit" hidden></button></form>`;
  $("drawerFoot").innerHTML = "";
  const first = $("drawerBody").querySelector("input, select, textarea");
  if (first) first.focus();
}
// Sauvegarde du formulaire "Envoi SMS" : valide le téléphone (10 chiffres), le formate
// en +1XXXXXXXXXX, détecte le bureau, ajoute la ligne localement (affichage immédiat,
// sans ouvrir la conversation) et déclenche onAjouterEnvoiSms pour la requête ajouterEnvoiSms.
function saveEnvoiSms() {
  const form = document.getElementById("envoiSmsForm"); if (!form) return;
  const errors = {}; const draft = {};
  const telRaw = (form.elements["telephone"]?.value ?? "").trim();
  const nomClientRaw = (form.elements["nomClient"]?.value ?? "").trim();
  draft.telephone = telRaw; draft.nomClient = nomClientRaw;
  let appelant = "";
  if (!telRaw) {
    errors.telephone = "Champ obligatoire";
  } else {
    const d = phoneDigits(telRaw);
    if (d.length !== 10) errors.telephone = "10 chiffres attendus, ex. (819) 555-1234";
    else appelant = "+1" + d;
  }
  state.errors = errors;
  if (Object.keys(errors).length) { state.draft = draft; renderDrawer(); return; }

  const bureau = detectBureauPourCreation();
  const maintenant = new Date().toISOString();
  const localId = "_new_envoi_" + Date.now();
  const newRecord = {
    id: localId, appelant, bureau, type: "Envoi SMS", statut: "Nouveau",
    smsAppel: "Non applicable", smsVocal: "Non applicable",
    date: maintenant, heure: fmtTime24(maintenant), derniereModification: maintenant,
    nomClient: nomClientRaw,
  };

  state.creatingEnvoi = false; state.draft = null; state.errors = {};
  appsmith.updateModel({
    appels: [...rowsOf("appels"), newRecord],
    nouvelEnvoiSms: { telephone: appelant, bureau, nomClient: nomClientRaw },
  });
  appsmith.triggerEvent("onAjouterEnvoiSms");
  state.selectedId = null;
  render();
  toast("Ligne ajoutée localement — écriture base de test pas encore branchée");
}

// ---------- Employés : formulaire (ajout et modification), enregistrement, suppression ----------
function injectEmployeStyles() {
  if (document.getElementById("employeStyle")) return;
  const st = document.createElement("style"); st.id = "employeStyle";
  st.textContent = `
  .edit-field[hidden] { display: none; }
  .edit-field .hint { display: block; margin-top: 5px; font-size: 12px; color: var(--muted); }
  .emp-roles, .emp-bureaux { display: grid; gap: 8px; }
  .emp-role:focus-within, .emp-bureaux label:focus-within { box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 18%, transparent); }
  .emp-role, .emp-bureaux label { position: relative; display: block; padding: 10px 12px; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--field-bg); cursor: pointer; }
  .emp-role:hover, .emp-bureaux label:hover { background: var(--hover); }
  .emp-role.on, .emp-bureaux label.on { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary) inset; }
  .edit-field .emp-role input, .edit-field .emp-bureaux input { position: absolute; opacity: 0; width: 1px; height: 1px; padding: 0; border: 0; pointer-events: none; }
  .emp-role .t { display: block; font-weight: 600; color: var(--text); }
  .emp-role .d { display: block; margin-top: 2px; font-size: 12px; color: var(--muted); }
  .emp-bureaux label { display: flex; align-items: center; gap: 10px; padding: 9px 12px; }
  .emp-bureaux .box { flex: none; width: 16px; height: 16px; border: 1.5px solid var(--line-strong); border-radius: 4px; display: grid; place-items: center; color: #fff; font-size: 11px; line-height: 1; background: var(--field-bg); }
  .emp-bureaux label.on .box { background: var(--primary); border-color: var(--primary); }
  .emp-bureaux label:not(.on) .box::after { content: ""; }
  .emp-bureaux label.on .box::after { content: "✓"; }
  .note-info { margin: 12px 0 4px; padding: 8px 10px; border-radius: 6px; background: var(--blue-bg); color: var(--blue-tx); font-size: 12px; }`;
  document.head.appendChild(st);
}

// Formulaire dédié (rôle en deux cartes, bureaux en cases à cocher). mode : "create" ou "edit" ; r = la personne (édition).
function renderEmployeForm(mode, r) {
  injectEmployeStyles();
  const d = state.draft || {};
  const val = (k, def) => (k in d ? d[k] : def);
  const nom = val("nom", r ? r.nom : "");
  const email = val("email", r ? r.email : "");
  const role = val("role", r ? r.role : "employe");
  const choisis = new Set(val("bureaux", r ? r.bureaux : []));
  const e = state.errors || {};
  const cartes = [
    ["employe", "Employé", "Voit seulement les données de son ou ses bureaux."],
    ["direction", "Direction", "Voit tous les bureaux et gère les employés."],
  ].map(([v, t, desc]) => `<label class="emp-role ${role === v ? "on" : ""}"><input type="radio" name="role" value="${v}" ${role === v ? "checked" : ""}><span class="t">${t}</span><span class="d">${desc}</span></label>`).join("");
  const cases = (model().bureaux || []).map((b) =>
    `<label class="${choisis.has(b) ? "on" : ""}"><input type="checkbox" name="bureaux" value="${esc(b)}" ${choisis.has(b) ? "checked" : ""}><span class="box"></span><span>${esc(b)}</span></label>`).join("");
  $("drawerBody").innerHTML = `<form id="employeForm" class="edit-form" novalidate>` +
    `<label class="edit-field"><span class="k">Nom complet</span><input name="nom" type="text" value="${esc(nom)}" placeholder="Prénom Nom" autocomplete="off"></label>` +
    `<label class="edit-field ${e.email ? "has-error" : ""}"><span class="k">Courriel <span class="req">*</span></span><input name="email" type="email" value="${esc(email)}" placeholder="prenom@exemple.ca" autocomplete="off">` +
      `${e.email ? `<span class="err">${esc(e.email)}</span>` : `<span class="hint">Doit être identique à l'adresse du compte Appsmith de la personne.</span>`}</label>` +
    `<div class="edit-field ${e.role ? "has-error" : ""}"><span class="k">Rôle <span class="req">*</span></span><div class="emp-roles">${cartes}</div>${e.role ? `<span class="err">${esc(e.role)}</span>` : ""}</div>` +
    `<div class="edit-field ${e.bureaux ? "has-error" : ""}" id="empBureauxBloc" ${role === "direction" ? "hidden" : ""}><span class="k">Bureaux <span class="req">*</span></span><div class="emp-bureaux">${cases}</div>` +
      `${e.bureaux ? `<span class="err">${esc(e.bureaux)}</span>` : `<span class="hint">Cochez tous les bureaux où cette personne travaille.</span>`}</div>` +
    `<button type="submit" hidden></button></form>`;
  $("drawerFoot").innerHTML = "";
  const premier = $("drawerBody").querySelector('input[name="nom"]');
  if (premier) premier.focus();
}

function ouvrirAjoutEmploye() {
  state.selectedId = null; state.editing = false; state.creating = false; state.creatingEnvoi = false;
  state.creatingEmploye = true; state.errors = {}; state.draft = null;
  renderGrid(); renderDrawer();
}

// Met à jour l'aspect du formulaire quand on change le rôle ou une case (cartes surlignées, bureaux masqués pour la direction).
function employeFormMaj() {
  const form = document.getElementById("employeForm"); if (!form) return;
  const role = (form.querySelector('input[name="role"]:checked') || {}).value;
  form.querySelectorAll(".emp-role").forEach((c) => c.classList.toggle("on", c.querySelector("input").checked));
  form.querySelectorAll(".emp-bureaux label").forEach((c) => c.classList.toggle("on", c.querySelector("input").checked));
  const bloc = document.getElementById("empBureauxBloc"); if (bloc) bloc.hidden = role === "direction";
}

function saveEmploye(mode) {
  const form = document.getElementById("employeForm"); if (!form) return;
  const r = mode === "edit" ? rowsOf("employes").find((x) => x.id === state.selectedId) : null;
  if (mode === "edit" && !r) return;
  const nom = (form.elements["nom"]?.value ?? "").trim();
  const email = emailNorm(form.elements["email"]?.value);
  const role = (form.querySelector('input[name="role"]:checked') || {}).value || "";
  const bureaux = role === "direction" ? [] : [...form.querySelectorAll('input[name="bureaux"]:checked')].map((x) => x.value);
  const draft = { nom, email, role, bureaux }; const errors = {};
  if (!email) errors.email = "Champ obligatoire";
  else if (!EMAIL_RE.test(email)) errors.email = "Adresse invalide, ex. prenom@exemple.ca";
  else if (employesGroupes().some((g) => g.email === email && (!r || g.email !== r.email))) errors.email = "Cette personne existe déjà : modifiez-la pour ajouter un bureau.";
  if (!role) errors.role = "Choisissez un rôle";
  else if (r && r.role === "direction" && role !== "direction" && employesGroupes().filter((g) => g.role === "direction").length <= 1) errors.role = "Il doit rester au moins une personne de la direction.";
  if (role === "employe" && !bureaux.length) errors.bureaux = "Choisissez au moins un bureau";
  state.errors = errors;
  if (Object.keys(errors).length) { state.draft = draft; renderDrawer(); return; }

  const ancien = r ? r.email : "";
  const creeLe = r && r.creeLe ? r.creeLe : new Date().toISOString();
  const cles = role === "direction" ? "*" : bureaux.join(",");
  const lignes = (role === "direction" ? [null] : bureaux).map((b, i) => ({ id: "_local_emp_" + Date.now() + "_" + i, email, nom, role, bureau: b, creeLe }));
  const autres = employesPlats().filter((l) => emailNorm(l.email) !== email && emailNorm(l.email) !== ancien);
  state.creatingEmploye = false; state.editing = false; state.draft = null; state.errors = {};
  appsmith.updateModel({
    employes: [...autres, ...lignes],
    employeSauvegarde: { ancienEmail: ancien, email, nom, role, cles, at: Date.now() },
  });
  appsmith.triggerEvent("onEnregistrerEmploye");
  state.selectedId = email;
  render();
  toast("Enregistrement en cours…");
}

// Retire des personnes (toutes leurs lignes de chat.employes). Garde-fous : jamais soi-même, toujours une personne de la direction.
function supprimerEmployes(ids) {
  const groupes = employesGroupes();
  const moi = emailNorm((model().app || {}).monEmail);
  const cibles = ids.filter((id) => id !== moi);
  if (cibles.length < ids.length) toast("Vous ne pouvez pas retirer votre propre accès.");
  if (!cibles.length) return;
  const direction = groupes.filter((g) => g.role === "direction");
  if (direction.length && direction.every((g) => cibles.includes(g.id))) { toast("Il doit rester au moins une personne de la direction."); return; }
  const [one, many] = VIEWS.employes.unit;
  const label = cibles.length > 1 ? `${cibles.length} ${many}` : `1 ${one}`;
  if (!window.confirm(`Retirer ${label} ? Cette personne n'aura plus accès à l'application.`)) return;
  state.checked.clear();
  if (state.selectedId && cibles.includes(state.selectedId)) state.selectedId = null;
  appsmith.updateModel({
    employes: employesPlats().filter((l) => !cibles.includes(emailNorm(l.email))),
    employesSupprimes: { emails: cibles.join(","), at: Date.now() },
  });
  appsmith.triggerEvent("onSupprimerEmploye");
  render();
  toast("Suppression en cours…");
}

// Diagnostic TEMPORAIRE de la page Employés : boîte jaune en bas à droite qui montre ce que le widget reçoit.
