// Rafraîchissement automatique. Au chargement de la page, Appsmith ne recalcule pas toujours le modèle quand les requêtes
// se terminent (il faut alors cliquer sur Run dans l'éditeur). Tant que des données manquent (model.chargement), le widget
// demande toutes les 2,5 s à EmployeManager.rafraichir() de relancer les requêtes manquantes et de forcer le recalcul,
// pendant 30 s au plus (même événement que l'enregistrement d'un employé : onEnregistrerEmploye avec charger:true).
const donneesManquantes = () => Object.values(model().chargement || {}).some((v) => v === true);
function demanderRafraichissement() {
  const t = Date.now();
  state.refreshAt = t;
  appsmith.updateModel({ employeSauvegarde: { charger: true, at: t } });
  appsmith.triggerEvent("onEnregistrerEmploye");
}
function actualiserSiBesoin() {
  if (!donneesManquantes()) return;
  if (Date.now() - (state.chargeDepuis || DEMARRE) >= 30000) return;
  if (Date.now() - (state.refreshAt || 0) < 2400) return;
  // Jamais pendant une saisie : le rafraîchissement redessine l'écran et viderait le formulaire en cours.
  if (state.creating || state.creatingEnvoi || state.creatingEmploye || state.editing) return;
  const actif = document.activeElement;
  if (actif && /^(INPUT|TEXTAREA|SELECT)$/.test(actif.tagName) && actif.id !== "searchInput") return;
  demanderRafraichissement();
}

// Résultat renvoyé par le JS Object EmployeManager (réussite ou échec) : affiché une seule fois.
function employeResultatSuivi() {
  const res = model().employeResultat;
  if (!res || !res.at || res.at <= Math.max(state.empDernier || 0, DEMARRE)) return;
  state.empDernier = res.at;
  toast(res.message || (res.ok ? "Enregistré." : "L'opération a échoué."));
}

// Sauvegarde d'une nouvelle ligne créée via le panneau "Nouveau". Ajoute la
// ligne localement (visible tout de suite) et signale l'événement pour
// qu'une query Appsmith puisse l'écrire réellement dans Airtable — cette
// écriture réelle n'est PAS encore branchée : tant qu'elle ne l'est pas, la
// ligne ajoutée est un brouillon local qui disparaîtra au prochain
// rafraîchissement des données.
function saveCreate() {
  const form = document.getElementById("createForm"); if (!form) return;
  const v = VIEWS[state.view];
  const errors = {}; const draft = {}; const values = {};
  EDIT[state.view].forEach((f) => {
    let val = (form.elements[f.key]?.value ?? "").trim();
    draft[f.key] = val;
    if (f.required && !val) errors[f.key] = "Champ obligatoire";
    if (f.type === "tel" && val) {
      const d = phoneDigits(val);
      if (d.length !== 10) errors[f.key] = "10 chiffres attendus, ex. (819) 555-1234";
      else val = `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
    }
    values[f.key] = val;
  });
  state.errors = errors;
  if (Object.keys(errors).length) { state.draft = draft; renderDrawer(); return; }

  const localId = "_new_" + Date.now();
  const newRecord = { id: localId, ...values };
  const me = (model().app && model().app.utilisateur) || "";
  if (state.view === "sms") {
    const complete = EDIT.sms.every((f) => !f.required || String(newRecord[f.key] || "").trim());
    newRecord.statut = complete ? "En attente" : "Champs incomplets";
    newRecord.ajoutePar = me;
    newRecord.dateAjout = new Date().toISOString();
  }
  if (state.view === "modeles") {
    newRecord.creePar = me;
    newRecord.modifiePar = me;
    if (estEmployeSimple()) newRecord.bureau = (model().app && model().app.monBureau) || "";
  }

  const rows = rowsOf(state.view);
  state.creating = false; state.draft = null; state.errors = {};
  appsmith.updateModel({
    [v.dataKey]: [...rows, newRecord],
    newRecord: { view: state.view, record: newRecord },
  });
  appsmith.triggerEvent(v.addEvent);
  state.selectedId = localId;
  render();
  toast("Ligne ajoutée localement — écriture Airtable pas encore branchée");
}

function saveEdit() {
  const form = document.getElementById("editForm"); if (!form) return;
  const v = VIEWS[state.view];
  const rows = rowsOf(state.view);
  const r = rows.find((x) => x.id === state.selectedId); if (!r) return;
  const changes = {}; const errors = {}; const draft = {};
  EDIT[state.view].forEach((f) => {
    let val = (form.elements[f.key]?.value ?? "").trim();
    draft[f.key] = val;
    if (f.required && !val) errors[f.key] = "Champ obligatoire";
    if (f.type === "tel" && val) {
      const d = phoneDigits(val);
      if (d.length !== 10) errors[f.key] = "10 chiffres attendus, ex. (819) 555-1234";
      else val = `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
    }
    if (val !== String(r[f.key] ?? "")) changes[f.key] = val;
  });
  state.errors = errors;
  if (Object.keys(errors).length) { state.draft = draft; renderDrawer(); return; }
  state.draft = null;
  if (!Object.keys(changes).length) { state.editing = false; renderDrawer(); toast("Aucune modification"); return; }

  if (state.view === "modeles" && estEmployeSimple() && modeleEstDefaut(r)) { personnaliserModele(r, String(changes.message ?? r.message ?? "")); return; }
  const updated = { ...r, ...changes };
  // Statut recalculé : un SMS complété repasse à « En attente », un SMS incomplet devient « Champs incomplets »
  if (state.view === "sms" && updated.statut !== "Envoyé") {
    const complete = EDIT.sms.every((f) => !f.required || String(updated[f.key] || "").trim());
    const newStatut = complete ? "En attente" : "Champs incomplets";
    if (newStatut !== updated.statut) { updated.statut = newStatut; changes.statut = newStatut; }
  }
  state.editing = false;
  appsmith.updateModel({
    [v.dataKey]: rows.map((x) => (x.id === r.id ? updated : x)),
    editedRecord: { view: state.view, id: r.id, changes, record: updated },
  });
  const eventParEtat = { sms: "onModifierSms", appels: "onModifierAppel", modeles: "onModifierModele" };
  appsmith.triggerEvent(eventParEtat[state.view]);
  render();
  toast("Modifications enregistrées");
}

let toastTimer;
function toast(msg, ms = 2200) {
  const t = $("toast"); t.textContent = msg; t.classList.add("show");
  clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove("show"), ms);
}

// Supprime les lignes dont les ids sont donnés — après confirmation, à la
// fois de l'affichage local et, via l'événement déclenché, de la vraie base
// de données (une query Appsmith de type DELETE doit écouter cet événement,
// voir VIEWS[view].deleteEvent). Partagée par le bouton "Supprimer" de la
// barre d'outils (sélection multiple) et le bouton corbeille du panneau de
// détail (une seule ligne).
function deleteRecords(ids) {
  const v = VIEWS[state.view];
  if (!v.deleteEvent || !ids.length) return;
  if (state.view === "employes") { supprimerEmployes(ids); return; }
  if (state.view === "modeles") {
    const lignes = rowsOf("modeles").filter((r) => ids.includes(r.id));
    const persos = lignes.filter(modeleEstPerso).map((r) => r.id);
    if (persos.length) {
      ids = ids.filter((id) => !persos.includes(id));
      toast("Pour revenir au texte par défaut, ouvrez la ligne et utilisez « Rétablir le défaut ».", 4500);
      if (!ids.length) return;
    }
    if (estEmployeSimple()) {
      const defauts = lignes.filter((r) => modeleEstDefaut(r) && !r.usage).map((r) => r.id);
      if (defauts.length) {
        ids = ids.filter((id) => !defauts.includes(id));
        toast("Seule la direction peut supprimer un texte par défaut.", 4500);
        if (!ids.length) return;
      }
    }
  }
  // Les messages automatiques (usage rempli) servent aux flux n8n : on ne les supprime pas.
  if (state.view === "modeles") {
    const auto = rowsOf("modeles").filter((r) => ids.includes(r.id) && r.usage).map((r) => r.id);
    if (auto.length) {
      ids = ids.filter((id) => !auto.includes(id));
      toast("Les messages automatiques ne peuvent pas être supprimés (les flux en ont besoin).", 4500);
      if (!ids.length) return;
    }
  }
  const [one, many] = v.unit;
  const label = ids.length > 1 ? `${ids.length} ${many}` : `1 ${one}`;
  const ok = window.confirm(`Supprimer ${label} ? Cette action est irréversible.`);
  if (!ok) return;

  const rows = rowsOf(state.view);
  const remaining = rows.filter((r) => !ids.includes(r.id));
  state.checked.clear();
  if (state.selectedId && ids.includes(state.selectedId)) state.selectedId = null;

  appsmith.updateModel({
    [v.dataKey]: remaining,
    deletedIds: { view: state.view, ids: ids },
  });
  appsmith.triggerEvent(v.deleteEvent);
  render();
  toast(`${label} supprimé(e)${ids.length > 1 ? "s" : ""} — synchronisation avec la base en cours`);
}

// Employé : « Modifier pour mon bureau » sur un texte par défaut -> requête personnaliserModeleBureau (crée ou met à jour le texte de SON bureau).
// Le bureau est imposé par la requête (celui de la personne connectée). Affichage immédiat, puis rechargement de getConfigurationSms.
function personnaliserModele(r, message) {
  const bureau = (model().app && model().app.monBureau) || "";
  state.editing = false;
  if (!bureau) { renderDrawer(); toast("Votre compte n'est associé à aucun bureau : voir la direction.", 4500); return; }
  const rows = rowsOf("modeles");
  const perso = { ...r, message, bureau, modeleDefaut: r.usage ? null : r.id };
  appsmith.updateModel({
    modeles: rows.map((x) => (x.id === r.id ? perso : x)),
    personnaliserModele: { defautId: r.id, message },
  });
  appsmith.triggerEvent("onPersonnaliserModele");
  render();
  toast("Texte de votre bureau enregistré — mise à jour en cours");
}
// « Rétablir le défaut » sur un texte personnalisé -> requête retablirModeleBureau (supprime la ligne du bureau ; le défaut redevient actif).
function retablirModele(id) {
  const r = rowsOf("modeles").find((x) => x.id === id);
  if (!r || !modeleEstPerso(r)) return;
  if (!window.confirm("Rétablir le texte par défaut ? La version personnalisée du bureau « " + r.bureau + " » sera supprimée.")) return;
  appsmith.updateModel({
    modeles: rowsOf("modeles").filter((x) => x.id !== id),
    retablirModele: { id },
  });
  appsmith.triggerEvent("onRetablirModele");
  state.selectedId = null; state.editing = false;
  render();
  toast("Texte par défaut rétabli — mise à jour en cours");
}

function performDelete() {
  deleteRecords([...state.checked]);
}

// Logo du client : app.logoUrl (venu de LOGO_URL dans le JS Object de configuration). Si l'image échoue ou n'est pas définie, l'icône par défaut reste.
// Règles anti-clignotement :
//  - l'icône par défaut (cachée dans le HTML au départ) ne s'affiche que si on SAIT qu'il n'y a pas de logo
//    (app.logoAbsent : liste reçue, sans logo) ou, en secours, après 4 s sans réponse (service d'upload en panne) ;
//  - le dernier logo connu est gardé dans la mémoire du navigateur et affiché tout de suite, avant l'arrivée des données.
const LOGO_DEBUG = false; // Trace des changements d'état du logo (boîte jaune en bas à gauche) : mettre true pour diagnostiquer un clignotement.
const LOGO_CACHE_CLE = "portail_logo_url";
const logoCacheLire = () => { try { return localStorage.getItem(LOGO_CACHE_CLE) || ""; } catch (e) { return ""; } };
const logoCacheEcrire = (u) => { try { if (u) localStorage.setItem(LOGO_CACHE_CLE, u); else localStorage.removeItem(LOGO_CACHE_CLE); } catch (e) { /* mémoire indisponible : sans effet */ } };
function logoTrace(app, decision) {
  if (!LOGO_DEBUG) return;
  const cle = [!!app.nom, app.logoChargement, app.logoAbsent, !!app.logoUrl, !!state.logoPret, decision].join("|");
  if (state.logoTraceCle === cle) return;
  state.logoTraceCle = cle;
  let box = document.getElementById("logoDebug");
  if (!box) {
    box = document.createElement("div"); box.id = "logoDebug";
    box.style.cssText = "position:fixed;left:4px;bottom:4px;z-index:99999;max-width:340px;font:11px/1.35 monospace;background:#fffbe6;color:#333;border:1px solid #e0c200;padding:4px 6px;white-space:pre-wrap";
    document.body.appendChild(box);
  }
  const v = (x) => (x === undefined ? "?" : +!!x);
  box.textContent += `${Math.round(performance.now())}ms nom=${+!!app.nom} chg=${v(app.logoChargement)} abs=${v(app.logoAbsent)} url=${+!!app.logoUrl} pret=${+!!state.logoPret} -> ${decision}\n`;
}
function renderLogo(app) {
  const img = $("brandLogo"); if (!img) return;
  const icone = document.querySelector(".brand svg.brand-ico");
  const icon = (visible) => { if (icone) icone.style.display = visible ? "" : "none"; };
  if (!state.logoDelaiLance) {
    state.logoDelaiLance = true;
    setTimeout(() => { state.logoPret = true; renderLogo(model().app || {}); }, 4000);
    const memo = logoCacheLire();
    if (memo) {
      img.onload = () => { img.hidden = false; icon(false); };
      img.onerror = () => { img.hidden = true; logoCacheEcrire(""); };
      img.src = memo;
    }
  }
  let decision;
  if (app.logoUrl) {
    decision = "logo";
    img.onerror = () => { img.hidden = true; icon(true); };
    img.onload = () => { img.hidden = false; icon(false); };
    if (img.getAttribute("src") !== app.logoUrl) img.src = app.logoUrl;
    else if (img.complete && img.naturalWidth > 0) { img.hidden = false; icon(false); }
    logoCacheEcrire(app.logoUrl);
  } else if (app.logoAbsent === true) {
    decision = "icone (aucun logo)";
    img.hidden = true; icon(true); logoCacheEcrire("");
  } else if (state.logoPret) {
    decision = "delai ecoule";
    if (img.hidden) icon(true);
  } else {
    decision = "attente";
    if (img.hidden) icon(false);
  }
  logoTrace(app, decision);
}

// ---------- Logo de l'entreprise (page Paramètres) ----------
// Le fichier choisi est lu ici (FileReader), puis passé à Appsmith : model.logoUpload + événement onTeleverserLogo
// (AssetManager.televerserLogo() -> uploadAsset.run -> listAssets.run). Le nouveau logo revient par app.logoUrl
// (voir logoUrl() dans le JS Object de configuration) et s'affiche partout sans autre action.
const LOGO_TYPES = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/svg+xml": "svg" };
const LOGO_MAX = 5 * 1024 * 1024;
const LOGO_BASE = "logo-entreprise"; // doit être identique à LOGO_BASE du JS Object de configuration
function injectLogoStyles() {
  if (document.getElementById("logoCardStyle")) return;
  const st = document.createElement("style"); st.id = "logoCardStyle";
  st.textContent = `
  .logo-card { display: flex; align-items: center; gap: 16px; margin: 12px 24px 4px 56px; padding: 14px 16px; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--surface); }
  .logo-card[hidden] { display: none; }
  .logo-card .lc-prev { width: 64px; height: 64px; flex: none; border: 1px solid var(--line); border-radius: 6px; background: #fff; display: flex; align-items: center; justify-content: center; overflow: hidden; }
  .logo-card .lc-prev img { max-width: 100%; max-height: 100%; object-fit: contain; }
  .logo-card .lc-txt { flex: 1; min-width: 0; }
  .logo-card .lc-titre { font-weight: 600; color: var(--text); }
  .logo-card .lc-aide { color: var(--muted); font-size: 12px; margin-top: 2px; }
  .logo-card .lc-etat { font-size: 12px; margin-top: 4px; color: var(--muted); }
  .logo-card .lc-etat.err { color: var(--danger); }
  .logo-card .btn { cursor: pointer; white-space: nowrap; }
  .logo-card .btn.busy { opacity: .5; pointer-events: none; }
  @media (max-width: 760px) { .logo-card { margin: 12px 12px 4px; } }`;
  document.head.appendChild(st);
}
function logoEtat(msg, erreur) {
  const e = document.getElementById("lcEtat"); if (!e) return;
  e.textContent = msg || ""; e.classList.toggle("err", !!erreur);
}
function renderLogoCard(app) {
  let card = document.getElementById("logoCard");
  // Seule la direction (ou, pendant la transition, une personne non encore inscrite dans chat.employes) change le logo.
  const enParametres = state.view === "modeles" && !!profilAcces().tous;   // bloc affiché sur la page Modèles SMS seulement
  if (!card) {
    if (!enParametres) return;
    injectLogoStyles();
    card = document.createElement("div"); card.id = "logoCard"; card.className = "logo-card";
    card.innerHTML = `<div class="lc-prev"><img id="lcImg" alt="" hidden></div>` +
      `<div class="lc-txt"><div class="lc-titre">Logo de l'entreprise</div>` +
      `<div class="lc-aide">PNG, JPG, WebP ou SVG · 5 Mo maximum · remplace le logo actuel</div>` +
      `<div class="lc-etat" id="lcEtat"></div></div>` +
      `<label class="btn primary" id="lcBtn">Changer le logo<input type="file" id="lcFile" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden></label>`;
    const wrap = $("gridWrap"); wrap.parentNode.insertBefore(card, wrap);
    $("lcFile").addEventListener("change", (e) => {
      const f = e.target.files && e.target.files[0]; e.target.value = "";
      if (f) televerserLogo(f);
    });
  }
  card.hidden = !enParametres;
  const img = $("lcImg");
  if (img) {
    if (app.logoUrl) {
      img.onload = () => { img.hidden = false; };
      img.onerror = () => { img.hidden = true; };
      if (img.getAttribute("src") !== app.logoUrl) img.src = app.logoUrl;
    } else img.hidden = true;
  }
  // Un téléversement attend son résultat : AssetManager le dépose dans model.logoResultat (succès ou erreur).
  const res = model().logoResultat;
  if (state.logoAttente && res && res.at >= (state.logoDebut || 0)) {
    state.logoAttente = false; clearTimeout(state.logoTimer);
    const btn = $("lcBtn"); if (btn) btn.classList.remove("busy");
    logoEtat(res.message || (res.ok ? "Logo mis à jour." : "Échec du téléversement."), !res.ok);
  } else if (state.logoAttente && app.logoUrl !== state.logoAvant) {
    // Secours : le logo a changé sans résultat explicite.
    state.logoAttente = false; clearTimeout(state.logoTimer);
    const btn = $("lcBtn"); if (btn) btn.classList.remove("busy");
    logoEtat("Logo mis à jour.", false);
  }
}
function televerserLogo(file) {
  const ext = LOGO_TYPES[file.type];
  if (!ext) { logoEtat("Format non permis : utilisez PNG, JPG, WebP ou SVG.", true); return; }
  if (file.size > LOGO_MAX) { logoEtat("Fichier trop volumineux (5 Mo maximum).", true); return; }
  const btn = $("lcBtn"); if (btn) btn.classList.add("busy");
  logoEtat("Téléversement en cours…", false);
  const reader = new FileReader();
  reader.onerror = () => { if (btn) btn.classList.remove("busy"); logoEtat("Fichier illisible, réessayez.", true); };
  reader.onload = () => {
    state.logoAvant = (model().app || {}).logoUrl || ""; state.logoAttente = true; state.logoDebut = Date.now();
    appsmith.updateModel({ logoUpload: { name: `${LOGO_BASE}.${ext}`, data: String(reader.result), at: Date.now() } });
    appsmith.triggerEvent("onTeleverserLogo");
    // Filet de sécurité : si rien ne revient (erreur côté serveur), on libère le bouton. Appsmith affiche déjà l'alerte d'erreur.
    clearTimeout(state.logoTimer);
    state.logoTimer = setTimeout(() => {
      if (!state.logoAttente) return;
      state.logoAttente = false; if (btn) btn.classList.remove("busy");
      logoEtat("Le téléversement n'a pas pu être confirmé. Réessayez ou contactez Ops.", true);
    }, 15000);
  };
  reader.readAsDataURL(file);
}

function render() {
  document.getElementById("app").classList.toggle("compact", state.density === "compact");
  const app = model().app || {};
  garderScopeAutorise();
  employeResultatSuivi();
  if (app.nom) $("brandName").textContent = app.nom;
  renderLogo(app);
  renderLogoCard(app);
  $("meAvatar").textContent = initials(app.utilisateur || "C");
  $("userName").textContent = app.utilisateur || "";
  $("userEmail").textContent = app.monEmail || "";
  renderNav(); renderTop(); renderTabs(); renderGrid(); renderFilterMenu(); renderDrawer(); renderNotifs();
  empTrace();
  chatSuivi();
}

// ---------- Interactions ----------
function closePopovers(except) {
  document.querySelectorAll(".popover.open").forEach((p) => { if (p !== except) p.classList.remove("open"); });
}

function bindEvents() {
  $("nav").addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    navigateTo(b);
  });
  $("crumbs").addEventListener("click", (e) => { if (e.target.closest("[data-crumb]")) { state.scope = "all"; state.tabs.appels = "all"; state.selectedId = null; render(); } });
  $("viewTabs").addEventListener("click", (e) => {
    if (e.target.closest("[data-ajout-employe]")) { ouvrirAjoutEmploye(); return; }
    const nouveau = e.target.closest("[data-nouveau-envoi]");
    if (nouveau) {
      state.selectedId = null; state.editing = false; state.creating = false; state.creatingEnvoi = true; state.errors = {}; state.draft = null;
      render();
      return;
    }
    const b = e.target.closest("[data-tab]"); if (!b) return;
    state.tabs[state.view] = b.dataset.tab; state.selectedId = null; state.checked.clear(); render();
  });

  $("thead").addEventListener("click", (e) => {
    if (e.target.closest(".resizer")) return;
    const th = e.target.closest("[data-sort]"); if (!th) return;
    const key = th.dataset.sort; const cur = state.sort[state.view];
    state.sort[state.view] = !cur || cur.key !== key ? { key, dir: "asc" } : cur.dir === "asc" ? { key, dir: "desc" } : null;
    render();
  });

  // Redimensionnement des colonnes
  $("thead").addEventListener("mousedown", (e) => {
    const h = e.target.closest(".resizer"); if (!h) return;
    e.preventDefault(); e.stopPropagation();
    const key = h.dataset.resize; const th = h.parentElement;
    const idx = [...th.parentElement.children].indexOf(th);
    const col = $("cols").children[idx];
    const startX = e.clientX; const startW = th.getBoundingClientRect().width;
    h.classList.add("dragging");
    const move = (ev) => { const nw = Math.max(70, startW + ev.clientX - startX); col.style.width = nw + "px"; state.widths[`${state.view}.${key}`] = nw; };
    const up = () => { h.classList.remove("dragging"); window.removeEventListener("mousemove", move); window.removeEventListener("mouseup", up); };
    window.addEventListener("mousemove", move); window.addEventListener("mouseup", up);
  });

  $("tbody").addEventListener("click", (e) => {
    if (e.target.closest("[data-add]")) {
      if (state.view === "employes") { ouvrirAjoutEmploye(); return; }
      if (!EDIT[state.view]) { appsmith.triggerEvent(VIEWS[state.view].addEvent); return; }
      state.selectedId = null; state.editing = false; state.creating = true; state.errors = {}; state.draft = null;
      renderGrid(); renderDrawer();
      return;
    }
    const chk = e.target.closest("[data-chk]");
    if (chk) { chk.checked ? state.checked.add(chk.dataset.chk) : state.checked.delete(chk.dataset.chk); renderGrid(); renderTop(); return; }
    const tr = e.target.closest("tr[data-id]"); if (!tr) return;
    state.selectedId = tr.dataset.id; state.editing = false; state.creating = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer();
  });

  $("drawer").addEventListener("click", (e) => {
    if (e.target.closest("[data-close]") || e.target.closest("#drawerClose")) {
      if (state.creatingEmploye) { state.creatingEmploye = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
      if (state.creatingEnvoi) { state.creatingEnvoi = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
      if (state.creating) { state.creating = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
      if (state.editing) { state.editing = false; state.errors = {}; state.draft = null; renderDrawer(); return; }
      state.selectedId = null; renderGrid(); renderDrawer(); return;
    }
    if (e.target.closest("#drawerEdit")) {
      if (state.creatingEmploye) { saveEmploye("create"); return; }
      if (state.creatingEnvoi) { saveEnvoiSms(); return; }
      if (state.creating) { saveCreate(); return; }
      if (state.editing) { if (state.view === "employes") saveEmploye("edit"); else saveEdit(); return; }
      state.editing = true; state.errors = {}; state.draft = null; renderDrawer(); return;
    }
    const retab = e.target.closest("[data-retablir]");
    if (retab) { retablirModele(retab.dataset.retablir); return; }
    if (e.target.closest("#drawerDelete")) {
      if (!state.selectedId) return;
      const lig = state.view === "modeles" ? rowsOf("modeles").find((x) => x.id === state.selectedId) : null;
      // Texte personnalisé d'un bureau : « supprimer » = revenir au texte par défaut (même action que « Rétablir le défaut »).
      if (lig && modeleEstPerso(lig)) retablirModele(lig.id); else deleteRecords([state.selectedId]);
      return;
    }
    if (e.target.closest("[data-cancel-edit]")) { state.editing = false; state.errors = {}; state.draft = null; renderDrawer(); return; }
    if (e.target.closest("[data-save]")) { saveEdit(); return; }
    const send = e.target.closest("[data-send]");
    if (send && !send.disabled) {
      appsmith.updateModel({ selectedSmsId: send.dataset.send });
      appsmith.triggerEvent("onEnvoyerSms");
    }
  });

  $("drawer").addEventListener("submit", (e) => {
    e.preventDefault();
    if (state.creatingEmploye) saveEmploye("create");
    else if (state.creatingEnvoi) saveEnvoiSms();
    else if (state.creating) saveCreate();
    else if (state.view === "employes") saveEmploye("edit");
    else saveEdit();
  });
  // Employés : cartes de rôle et cases des bureaux (surlignage, bureaux masqués pour la direction)
  $("drawerBody").addEventListener("change", (e) => { if (e.target.closest && e.target.closest("#employeForm")) employeFormMaj(); });

  $("deleteBtn").addEventListener("click", () => performDelete());

  $("filterBtn").addEventListener("click", (e) => { e.stopPropagation(); const m = $("filterMenu"); closePopovers(m); m.classList.toggle("open"); });
  $("filterMenu").addEventListener("click", (e) => e.stopPropagation());
  $("filterMenu").addEventListener("change", (e) => {
    const val = e.target.dataset.filter; if (val === undefined) return;
    const f = state.filters[state.view]; e.target.checked ? f.add(val) : f.delete(val);
    renderTop(); renderGrid();
  });
  $("filterMenu").addEventListener("click", (e) => {
    if (e.target.closest("[data-filter-reset]")) { state.filters[state.view].clear(); render(); $("filterMenu").classList.add("open"); }
  });

  $("sortBtn").addEventListener("click", () => {
    state.sort[state.view] = state.sort[state.view] ? null : { ...VIEWS[state.view].defaultSort };
    render();
  });

  $("viewBtn").addEventListener("click", (e) => { e.stopPropagation(); const m = $("viewMenu"); closePopovers(m); m.classList.toggle("open"); });
  $("viewMenu").addEventListener("click", (e) => {
    const b = e.target.closest("[data-density]"); if (!b) return;
    state.density = b.dataset.density; $("viewMenu").classList.remove("open"); render();
  });

  $("searchBtn").addEventListener("click", () => {
    const box = $("searchBox"); box.classList.toggle("open");
    if (box.classList.contains("open")) $("searchInput").focus();
  });
  $("searchInput").addEventListener("input", (e) => { state.search = e.target.value; renderGrid(); });

  // Menu du compte (avatar)
  $("meAvatar").addEventListener("click", (e) => { e.stopPropagation(); const m = $("userMenu"); closePopovers(m); m.classList.toggle("open"); });
  $("userMenu").addEventListener("click", (e) => {
    if (e.target.closest('[data-action="logout"]')) appsmith.triggerEvent("onSeDeconnecter");
  });

  // Notifications (cloche)
  $("bellBtn").addEventListener("click", (e) => { e.stopPropagation(); const p = $("notifPanel"); closePopovers(p); p.classList.toggle("open"); renderNotifs(); });
  $("notifPanel").addEventListener("click", (e) => {
    e.stopPropagation();
    const tab = e.target.closest("[data-ntab]");
    if (tab) { state.notif.tab = tab.dataset.ntab; renderNotifs(); return; }
    const it = e.target.closest("[data-nid]");
    if (it) { openAlert(it.dataset.nid); return; }
    if (e.target.closest("#notifMarkAll")) { computeAlerts().forEach((a) => state.notif.read.add(a.id)); renderNotifs(); }
  });
  $("notifSearch").addEventListener("input", (e) => { state.notif.q = e.target.value; renderNotifs(); });

  $("collapseBtn").addEventListener("click", () => setRail(!isRail()));
  $("expandBtn").addEventListener("click", () => setRail(false));
  $("drawerBody").addEventListener("click", (e) => {
    const t = e.target.closest("[data-drawer-tab]"); if (!t) return;
    state.drawerTab = t.dataset.drawerTab; renderDrawer();
    if (state.drawerTab === "chat") {
      const rr = rowsOf("appels").find((x) => x.id === state.selectedId);
      if (rr && chatPossible(rr)) chatMarquerLu(rr);
    }
  });
  // Onglet « Planification » : saisie mémorisée + bouton « Planifier le SMS »
  $("drawerBody").addEventListener("input", planifSaisie);
  $("drawerBody").addEventListener("change", planifSaisie);
  $("drawerBody").addEventListener("click", (e) => { if (e.target.closest("#planifAjouter")) planifAjouterClic(); });
  $("drawerBody").addEventListener("input", (e) => {
    if (e.target.id !== "chatTexte") return;
    const r = rowsOf("appels").find((x) => x.id === state.selectedId);
    if (r) state.brouillons[r.id] = e.target.value;
    chatSaisieMaj();
  });
  $("drawerBody").addEventListener("change", (e) => {
    if (e.target.id !== "chatModele" || !e.target.value) return;
    const m = (Array.isArray(model().modeles) ? model().modeles : []).find((x) => x.id === e.target.value);
    const zone = $("chatTexte");
    if (m && zone) {
      zone.value = zone.value.trim() ? zone.value.replace(/\s+$/, "") + "\n" + m.message : m.message;
      zone.dispatchEvent(new Event("input", { bubbles: true }));
      zone.focus();
    }
    e.target.value = "";
  });
  $("drawerBody").addEventListener("keydown", (e) => {
    if (e.target.id === "chatTexte" && e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); chatEnvoyerClic(); }
  });
  $("drawerBody").addEventListener("click", (e) => {
    if (e.target.closest("#chatEnvoyer")) chatEnvoyerClic();
  });
  // Molette sur le fil de messages : il défile seul ; arrivé au bout, la page derrière ne bouge pas.
  // Ailleurs dans le panneau, et si le fil n'a rien à défiler, le comportement normal du navigateur est conservé.
  $("drawer").addEventListener("wheel", (e) => {
    const fil = e.target.closest ? e.target.closest(".chat-fil") : null;
    if (!fil || !e.deltaY || fil.scrollHeight <= fil.clientHeight) return;
    const peutHaut = e.deltaY < 0 && fil.scrollTop > 0;
    const peutBas = e.deltaY > 0 && fil.scrollTop + fil.clientHeight < fil.scrollHeight - 1;
    if (!peutHaut && !peutBas) e.preventDefault();
  }, { passive: false });
  bindRail();

  document.addEventListener("click", () => closePopovers());
  // Bouton « Actualiser » (affiché quand le chargement a échoué) : relance 30 s de tentatives automatiques.
  document.addEventListener("click", (e) => {
    if (!(e.target.closest && e.target.closest("[data-refresh]"))) return;
    state.chargeDepuis = Date.now(); demanderRafraichissement(); render();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    closePopovers();
    if (state.creatingEmploye) { state.creatingEmploye = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
    if (state.creatingEnvoi) { state.creatingEnvoi = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
    if (state.creating) { state.creating = false; state.errors = {}; state.draft = null; renderGrid(); renderDrawer(); return; }
    if (state.editing) { state.editing = false; state.errors = {}; state.draft = null; renderDrawer(); return; }
    if (state.selectedId) { state.selectedId = null; renderGrid(); renderDrawer(); }
  });
}

// ---------- Démarrage ----------
// Vérifie que le HTML collé est bien celui de ce widget (sinon message clair au lieu d'un crash)
const REQUIRED_IDS = ["app", "nav", "brandName", "meAvatar", "userMenu", "userName", "userEmail", "bellBtn", "notifPanel", "notifSearch", "notifList", "notifMarkAll", "notifCount", "collapseBtn", "expandBtn", "sideResizer", "railFlyout", "sidebar", "crumbs",
  "pageDesc", "viewTabs", "searchBox", "searchInput", "deleteBtn", "deleteCount", "filterBtn", "filterCount", "filterMenu", "sortBtn", "sortCount", "viewBtn",
  "densityLabel", "viewMenu", "searchBtn", "cols", "thead", "tbody", "empty", "foot",
  "drawer", "drawerTitle", "drawerEdit", "drawerDelete", "drawerClose", "toast", "drawerBody", "drawerFoot"];

appsmith.onReady(() => {
  const missing = REQUIRED_IDS.filter((id) => !document.getElementById(id));
  if (missing.length) {
    const msg = "HTML incompatible avec ce JS. Éléments introuvables : #" + missing.join(", #") +
      ". Colle le widget.html qui commence par « <!-- Widget custom Appsmith — Portail SMS / Appels manqués (onglet HTML) --> ».";
    console.error(msg);
    document.body.innerHTML = '<div style="font:14px system-ui;padding:24px;color:#9b1c12">' + msg.replace(/</g, "&lt;") + "</div>";
    return;
  }
  theme.monter();
  theme.depuisModele();
  bindEvents();
  render();
  appsmith.onModelChange(() => { theme.depuisModele(); render(); });
  setInterval(actualiserSiBesoin, 2500);
  appsmith.triggerEvent("onWidgetReady");
});
